quests[14274] = { id = 14274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "It is true then!  You live!\n\nI never got a chance to share my greatest discovery with you.  After I began my training, and began to become accomplished, I heard the voice Balcephoth of the felshadows in my head... he taught me the forbidden secrets of...\n\nCorruption!\n\nGo now, gain some more experience, maybe you'll learn a new spell, too. You can go use it against the Bloodfang Worgen to our west.", completion = "Yes!  You can feel the power, can't you?", objectives = "Reach level 3 to learn Corruption. Practice casting it on a Bloodfang Worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14275] = { id = 14275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone's Keeping Track of You", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A man named Blake.  Said something about a plan to escape into the woods.", completion = "{name}!  I knew you had to be around here.", objectives = "Speak to Huntsman Blake in the Military District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14276] = { id = 14276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Shot", description = "So I've got good news and bad news.\n\nThe bad news is that there are more worgen in the woods than in here... so we really have no safe place to go to.\n\nThe good news is that you're starting to get the hang of this. As you get more experience, you'll start to learn how to do new things.\n\nOnce you learn your first new ability, try your hand at it against the bloodfang worgen to our west.", completion = "Excellent work, {name}.  These {race} will regret ever setting foot in our lands.", objectives = "Reach level 3 to learn Steady Shot. Practice using Steady Shot 2 times against a Bloodfang Worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14277] = { id = 14277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Inquiries", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  It was a mage named Myriam.  She mentioned something about you being \"ready.\"", completion = "A disciple of the arcane always finds a way forward.  I'm glad to see you, {name}.", objectives = "Speak to Myriam Spellwaker in the Military District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14278] = { id = 14278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Sister", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A member of the clergy, Sister Almyra, said that you were in great peril and needed the Light's protection.\n\nYou should go talk to her.  She seemed very concerned.", completion = "The Light is with you, {name}.  It's still quite a relief to see you.", objectives = "Speak to Sister Almyra in the Military District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14279] = { id = 14279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "You have much to learn, {name}.  And I've much to teach you.\n\nThese are perilous times, however, and I fear that you may need to learn much on your own\n\nHave no fear, <brother/sister>.  The Light will guide us through this.\n\nGo, get more experience, and learn a new skill. Use it against the bloodfang worgen nearby.", completion = "You are blessed, {name}.  The Light shines upon you, even in these dark times.", objectives = "Reach level 3 to learn Shadow Word: Pain. Use it 2 times on a bloodfang worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14280] = { id = 14280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Winds Know Your Name... Apparently", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  It was that harvest-witch, Celestine; she said the winds spoke your name.\n\nYou'd best hurry, {name}.  We're going to need you to get back to the worgen-smashing once you're done conversing with nature.", completion = "We have been blessed today!  You are alive and well!", objectives = "Speak to Celestine of the Harvest in the Military District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14281] = { id = 14281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Nova", description = "The path ahead is difficult, {name}.  We must devote the entirety of our mental power to the task at hand.\n\nAs you begin to grow in power, new pathways to the arcane will begin to materialize in your mind. You'll begin to develop spells you did not know before.\n\nGo, get more experience, and then use what you learn against the Bloodfang Worgen.", completion = "You've learned with such speed and ease.  Soon you'll be the one doing the teaching.", objectives = "Reach level 3 to learn Frost Nova. Use it against a Bloodfang Worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14282] = { id = 14282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Solved", description = "Your efforts have paid off. The great risks you have taken have proven worthwhile.\n\nYou have discovered the object of the nagas' desire and their reason for overrunning the coast of Desolace.\n\nAs for the engravings you've discovered, your duty is clear...", progress = "What have you learned, {class}?", completion = "The vision was true!\n\nYou have singlehandedly succeeded where others have failed.\n\nThe Circle will have no choice but to pay attention to these findings.", objectives = "You are to bring the Ancient Engravings of Neptulon to Cenarion Researcher Korrah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14283] = { id = 14283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonfire", description = "We were driven to the edge of extinction once before, {name}.  But we druids, keepers of the old ways, saved our people from famine.\n\nWhen we cut ourselves off from the outside world and our crops failed, it was our order who called upon the earth's blessings and restored the harvest.\n\nJust as our powers restored the crops, your growth in power will develop your connection to our ancient arts.\n\nGo, develop your powers, and use what you learn against the Bloodfang Worgen.", completion = "Not bad at all.  Perhaps there is still hope for the old ways.", objectives = "Reach level 3 to learn Moonfire, then use it against a Bloodfang Worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14284] = { id = 14284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Revenant's Vengeance", description = "I am Hydronis, a servant of Neptulon the Tidehunter, Lord over all waters.\n\nAzshara and her sinister naga have arrayed themselves against my master, and seek a war with him. This is the first battle in what shall surely be a long struggle.\n\nI have fought bitterly, {race}, and have grown weary.\n\nIt seems that my actions here have attracted the attention of their priestess.\n\nAlone, I haven't the strength to overcome her. but perhaps together, we may prevail.", completion = "The priestess is no more...", objectives = "Hydronis wants you to mount him and defeat Priestess Valishj.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14285] = { id = 14285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "There's only so much I can teach right now with all these worgen trying to dismember us.\n\nWe really should think about heading south with the other survivors.  We've been told that King Greymane is there.\n\nIf we stick together our chances of survival will increase... especially if you choose someone nutritious-looking to stand next to.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", objectives = "Speak to King Genn Greymane in the military district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14286] = { id = 14286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", objectives = "Speak to King Genn Greymane in the military district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14287] = { id = 14287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", objectives = "Speak to King Genn Greymane in the military district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14288] = { id = 14288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "There's only so much I can teach right now with all these worgen trying to dismember us.\n\nWe really should think about heading south with the other survivors.  We've been told that King Greymane is there.\n\nIf we stick together our chances of survival will increase... especially if you choose someone nutritious-looking to stand next to.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", objectives = "Speak to King Genn Greymane in the military district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14289] = { id = 14289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nThe others are going to need the aid of the Light in these troubling times.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", objectives = "Speak to King Genn Greymane in the military district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14290] = { id = 14290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", objectives = "Speak to King Genn Greymane in the military district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14291] = { id = 14291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", objectives = "Speak to King Genn Greymane in the military district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14292] = { id = 14292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of Our Enemy", description = "You have done us a great service, {class}.\n\nWhile they remain an imposing force, your efforts have kept an important artifact from the naga.\n\nI shall write to my peers of your findings. Meanwhile, the water revenant on Ranazjar Isle has stood alone against a steady onslaught of naga.\n\nI would have you find him and determine if there is some way we can assist him.", completion = "I have witnessed your actions here, {race}.\n\nYour presence here is both welcome and timely.", objectives = "Cenarion Researcher Korrah wants you to speak with Lord Hydronis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14293] = { id = 14293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Krennan Aranas", description = "All these years after the war and Crowley was still hiding enough firepower in that cellar to level half of the district.\n\nIt might have to come to that, unfortunately.\n\nWe can't open fire just yet, there is a civilian trapped on the other side of the prison.\n\nNot just any civilian, either.  Krennan Aranas is one of the most brilliant alchemists this world has known.\n\nOne of his potions saved my daughter, Tess, from dying soon after being born.\n\nTake my horse and rescue him.  Krennan must live.", completion = "Well done, {name}.  We'll make sure Krennan makes it out of the city alive.", objectives = "Rescue Krennan Aranas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14294] = { id = 14294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Regroup", description = "We've done all we can here.  Let King Greymane know we've bought some time.\n\nI've a feeling it won't be long 'til the worgen are back in force.\n\nWe'll need to fall back to Greymane Court to the west, if that's the case.  It's the last place we can hold out without being trapped like fish in a barrel.", completion = "We're left with very few choices, {name}.  What we do next will be a critical decision.", objectives = "Speak to King Genn Greymane at Greymane Court in Gilneas City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14295] = { id = 14295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sisters of the Sea", description = "Two Naga witches have been masterminding the assault on this outpost. They've repelled direct attacks from some of my best grunts, but you can finish the job where others have failed.\n\nSeek out and slay Lady Silisthra and Lady Vesthra at the eastern edge of the cliffs, around the ruins of the ancient night elven colossus. You will first need to destroy the powerstones that give them their strength. Do not disappoint me, {class}!", completion = "Now THAT is how we used to handle serpents back in Durotar - we crushed them under our boots! You have done the Horde proud, {name}. As soon as my reinforcements arrive we'll mop up the rest of those vermin and claim this peninsula once and for all.", objectives = "Kill Lady Silisthra and Lady Vesthra by disabling their power stones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14296] = { id = 14296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch Your Step", description = "This is somewhat simple and somewhat not simple. All the way up there are Energy Conduits. Rather like this one right here one might say! Indeed, I do say.\n\nNow for you. You must use my jump pads to ascend the pinnacle, and you must touch all of the conduits you see along the way. When you get to me at the top, you should be all juicy with energy, because really that's the only way to be.\n\nAnd be sure to keep moving or you're likely to be sent for quite a trip!", progress = "No no no, you've got it all wrong. You were supposed to gather Energy from the Conduits before you came up here, remember?\n\nOne more time, with style!", completion = "It is in this moment that most of my apprentices wonder if there was a logical purpose to storing the energy for my portal in those conduits so that it has to be collected in such a fashion.\n\nOf course there's a purpose! I wish to study your behavior... your strategies, your mistakes, your frustrations, your triumphs. Those are the entire point of these trials.\n\nNow, more. More trials! Doesn't that sound exciting?! Of course it does.", objectives = "Receive 6 Energized charges from the Energy Conduits as you ascend to the top of the Arcane Pinnacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14297] = { id = 14297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pro-liberation", description = "I knew these guys would be trouble as soon as we started building this tower. Scoffing our bribes. Stealing our workers.\n\nLabor isn't cheap with all the construction in Azshara. I need those men back!", progress = "There's no way I'm paying them for time in captivity. Greedy little punks.", completion = "Thanks there, pal. Here's your commission.\n\nIf you'll excuse me, I've gotta get these slackers back to work.", objectives = "Use Ironwrought Keys from cultists and dragonkin to free 4 Goblin Workers in Sable Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14298] = { id = 14298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Cultists/Dragonflight" }
quests[14299] = { id = 14299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xylem's Asylum", description = "Quite marvelous of you! A pleasure to observe. Much to study.\n\nOff you go now, retire to my tower. Joanna will get you situated. I shall open a portal for you.", completion = "Welcome! You seem to have survived the trials relatively unscathed. Good for you, love.\n\nYou look to have come with a purpose in mind as well. A question. Your thoughts are very loud, it's hard for me to not hear them.\n\nGo ahead then, hon. Ask away.", objectives = "Take the portal to Archmage Xylem's tower and seek out Joanna inside.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14300] = { id = 14300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Fire", description = "The Trial of Fire... oooh... sounds intimidating, doesn't it? No? Hm. Well I kind of thought so. Firsts are first, you touch the fire crystal and the portal to the trial opens.\n\nTo beat this trial, you have to hop around in the fire runes without getting hit by the fire. If you stay unflamed long enough, you win!\n\nThere are little signs to help you - fire hopping to its new rune, fizzles when a rune goes cold. You can figure that stuff out if you want. Or just guess! That's what most people do.", progress = "Um, no. You're not done. Get back in there and get toasty!", completion = "Woo! Good for you! That trial really put a fire under your bottom.", objectives = "Complete the Trial of Fire by standing in the fire runes without getting hit by flame for 10 consecutive bursts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14301] = { id = 14301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return and Report", description = "It is done! Together we were able to bring down a dangerous adversary.\n\nNeptulon himself shall hear of your exploits here, {class}. Allow me to extend you his thanks...\n\nYou should leave now. This place will not remain safe for long. Soon, the naga will seek vengeance for their priestess.", completion = "Please accept this reward for your heroic accomplishments, {name}.\n\nYou have bought us precious time!", objectives = "You are to return to Cenarion Researcher Korrah at Ethel Rethor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14302] = { id = 14302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Official Assessment", description = "You have accomplished much in your efforts against the naga, {name}. But I fear it is not nearly enough....\n\nThis is my official assessment of the naga presence.\n\nI'm confident that my peers in the wildlands will take the necessary action.\n\nBring this to Karnum at the glade in the center of the Cenarion Wildlands to the southeast. He will know what to do.\n\nThank you, {name}. And farewell.", completion = "<Karnum opens and reads Korrah's Report.>\n\nThis is alarming news, indeeed, {race} - something we have no shortage of here.\n\nI shall call a council regarding the issue. You will be summoned if you are needed.", objectives = "Cenarion Researcher Korrah wants you to take Korrah's Report to Karnum at Karnum's Glade.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14303] = { id = 14303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Aggra", description = "Return to the Horde Base Camp and let Aggra know that we still live, {name}.\n\nTell her that I am moving on to the Wild Overlook and that we will all meet up on the northwest side of the island. I expect to see you there.\n\nWe will track down the Alliance and slay them to the last!", completion = "<Aggra gives you the eye as if she doesn't quite believe what you are telling her.>\n\nI am not easily impressed, but if what you are telling me is true, then I have never before heard of such a thing.\n\nYou have my thanks, {name}.", objectives = "Inform Aggra at the Horde Base Camp on the Lost Isles of all that has transpired.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14304] = { id = 14304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Theory", description = "The land is not all that has changed in Desolace. Here, the wildlife has responded to their new environment in strange and sometimes exciting ways.\n\nI am particularly interested in the Rejuvenated Thunder Lizards that roam just to the west.\n\nI need a sample of their blood.\n\nYou may begin helping me by using this jar of leeches on a few of them.\n\nOnce they've filled on the blood of those beasts, return them to me.", progress = "Were you able to recover the samples I require?", completion = "This should be enough.\n\nThank you, {class}.", objectives = "Collect 10 Blood-filled Leeches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14305] = { id = 14305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Reap", description = "No one knows better than the Cenarion Circle that this lush oasis could dry up as quickly as it appeared.\n\nWe must take care not to interfere with the processes taking place here, but to support and preserve them,\n\nA new species of plant, very plentiful in the surrounding region, has appeared since the great change.\n\nCollect samples of these for me, that I might study them and learn what they have to teach us,", progress = "Have you collected the samples I require?", completion = "These are fine specimens, {race}.\n\nI shall commence my studies immediately.", objectives = "Collect 10 Aloe Thistles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14306] = { id = 14306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulling Weeds", description = "With such an abrupt change to the ecology, it is to be expected that some of the flora and fauna don't react as well as we'd hope.\n\nThe uprooted lashers are a troublesome example of this. Roaming the fields to the east and south they are a detriment to the region and must be disposed of.\n\nWhile you're about, please deal with any of these pests that you find.", progress = "Have you helped to deal with the lasher problem, {class}?", completion = "On behalf of Desolace herself, I thank you, {race}.\n\nPlease accept our deepest gratitude.", objectives = "Kill 7 Uprooted Lashers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14307] = { id = 14307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stubborn Winds", description = "The winds of change are blowing, {race}. Of that there can be no doubt.\n\nThere are many pressing issues vying for our attention and action. Chief among them is the spreading of our growing oasis.\n\nIts growth has surpassed our hopes as well as our understanding, yet now it faces opposition.\n\nTo the west, where the grass meets the sand, whirlwinds prevent its penetration into the desert.\n\nGo and eliminate this hostile obstacle to life!", progress = "How goes our plight to the west?", completion = "You have done well, {class}.\n\nWe will doubtlessly call upon you for assistance with more significant matters in the future.", objectives = "Destroy 5 Whirlwind Stormwalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14308] = { id = 14308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Science Attacks", description = "Did you see the explosions on the way in? The Secret Lab is engulfed in flames! Again! If we don't stamp out those flames we're going to hit critical temperatacity and resonate into a meltdown cascade.\n\nHere, I'm entrusting you with a canister of experimental hypercooled pressurized liquigel: The most volatile fire retardant known to science! (Keep that canister away from open flame.) Put out the fires and hose down my interns, then contact me via the squawkbox in central control.", progress = "<Greely's squeaky voice peels through a set of speakers.>\n\nRocketway to Secret Lab! Rocketway to Secret Lab! Come in, Secret Lab...", completion = "Nice work, {name}! Now, we need to decouple the reaction core matrix from the fuel sumps, or that whole place is gonna blow itself to Outland...", objectives = "Use the Fireliminator X-21 to extinguish 8 fires and to rescue 6 Research Interns from the inferno at the Secret Lab.\n\nSee Assistant Greely at the Southern Rocketway Terminus if you lose your Fireliminator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14309] = { id = 14309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calming the Kodo", description = "As you have by now witnessed, the rapid changes to this region can have both positive and negative effects on the native creatures.\n\nTo the south and east of here, enraged kodo are a constant threat to anyone nearby.\n\nIt's time to put my theory to the test. I've used the rejuvenated thunder lizard's blood in the making of this concoction. I'm hoping it will soothe the kodo when they eat it.\n\nPlace it near an enraged kodo and make sure you do it from a safe distance!", completion = "Wonderful! Karnum will be so pleased!\n\nPlease, accept this as my thanks.", objectives = "Use the Kodo Concoction near 5 Enraged Kodos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14310] = { id = 14310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segmentation Fault: Core Dumped", description = "Once we flush the central reactor, I need you to return the core to me. It's 100% refined azsharite crystal, which is both powerful and dangerous. And lovely. Oh precious azsharite, the shaper of worlds to come!\n\nThe giant lever to your left will dump the core and send it to me via the rail system. The core will be superheated, so you'll need to periodically douse it with the Fireliminator on the way here... don't let it reach critical temperature!", progress = "Don't worry about the residual effects of all those burning chemicals in the lab. Hair grows back!", completion = "Whew, the sample is secure. And it's still steaming! Thank you, {name}.\n\nAzsharite is a complex mystery wrapped in a velvety enigma of danger. Grapplehammer insists that we learn more about this strange substance.", objectives = "Activate the Reactor Control Console and escort the Azsharite Core back to the Southern Rocketway Terminus. Use the Fireliminator X-21 on the Core if it starts to overheat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14311] = { id = 14311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Part", description = "What a glorious time we live in!\n\nThe former wastelands of Desolace are blooming, bursting with life. Imagine, {class}, if all of Azeroth's wastelands awoke in such a fashion! Perhaps someday...\n\nIt's true that there are weighty issues at hand here, but why not take a moment to appreciate the wondrous miracle we are witnessing?\n\nIn fact, why not take part in it? Here are some Cenarion Seeds. Use them at the more fertile spots of the wildlands.\n\nPerfect medicine for lifting a weary soul!", completion = "The rejuvenation is so invigorating! Don't you think?", objectives = "Use the Cenarion Seeds next to 5 of the Fertile Mounds around the Cenarion Wildlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14312] = { id = 14312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Introduction Is In Order", description = "I have heard of your exploits here in Desolace, {name}. We are in your debt.\n\nI'm afraid I must involve you in yet another crisis, one more pressing than the rest.\n\nThe landscape is not all that has changed here of late. Old conflicts have made way for new, more dire ones. I should allow our guest to explain further....\n\nKhan Leh'prah is among the last of the Kolkar tribe that once possessed all of eastern Desolace. We found him near death on our borders. Listen to his words.", completion = "Be not afraid, {race}. I mean you no harm.", objectives = "Garren Darkwind at Karnum's Glade wants you to speak to Khan Leh'prah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14313] = { id = 14313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among Humans Again", description = "So Krennan's potion did not kill you?  Well, I suppose that means the human inside of you is in control then.\n\nI guess I won't be shooting you after all.  At least not yet.\n\nGo speak to Krennan Aranas and give him the good news.  He's in charge of the house where we keep... your kind.\n\nJust remember, {name}.  I've got my eye on you.  You so much as try anything funny and you'll get a bullet between the eyes.", completion = "It worked!  By the Light, it worked!", objectives = "Speak to Krennan Aranas in Duskhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14314] = { id = 14314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breakout!", description = "It began with a dream that repeatedly warned me of the danger to come. I saw the demonic legions bearing down upon our kind, overrunning our lands.\n\nThe dream has become real. The Burning Blade and their demon masters have pushed the Magram out of their lands in the south. In turn, the Magram have defeated my people and taken over our homes.\n\nThe fight was ferocious. Only a handful of the Kolkar still live. I would ask that you visit what was once my land in the east, and free them from their prison.", completion = "I thank you, {race}.\n\nOur tribe may not have survived without your aid.", objectives = "Kill the Magram Warden at the Magram Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14315] = { id = 14315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liam's Stupor", description = "Go away!  You're just inside my head... You're not real.... you're dead!\n\nYou died in Gilneas City... the worgen... they got you...\n\nIt should've been me... it should've been me...\n\nAughhh... first the earth won't stop moving... and now I'm seeing things...  too much rye...\n\n<The prince seems out of it.  Perhaps you can find someone else to speak to.>", sourceObjective = "Speak to Gwen Armstead in Duskhaven.Go away!  You're just inside my head... You're not real.... you're dead!\n\nYou died in Gilneas City... the worgen... they got you...\n\nIt should've been me... it should've been me...\n\nAughhh... first the earth won't stop moving... and now I'm seeing things... too much rye...\n\n<The prince seems out of it. Perhaps you can find someone else to speak to.>", sourceObjectiveStatus = "unverified-source-field" }
quests[14316] = { id = 14316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarion Property", description = "Since the demons have invaded their lands, the Magram have broken all ties with any outsiders.\n\nThey are untrusting and hostile and have taken to stealing from others instead of providing for themselves.\n\nMany of our needed supplies have gone missing of late and we suspect that the Magram are to blame.\n\nPlease, {name}, go to their lands in the east and search for our belongings.", progress = "Were you able to find our belongings, {name}?", completion = "As we suspected, the Magram have been stealing our supplies.\n\nWe shall guard them more closely.", objectives = "Collect 7 Cenarion Supply Crates from the Magram Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14317] = { id = 14317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tremors", description = "{name}!  We thought we wouldn't see you again!\n\nListen -- we need your help. A huge earthquake hit us and the aftershocks haven't stopped.  Prince Liam isn't going to be of much use either.\n\nWe need to make sure our defenses are still holding up.  The Queen's Gate is the only thing standing between us and a mess of frothing-at-the-mouth rabid worgen from the Blackwald.\n\nJust follow the road east, out of town.  Let me know if the gate has held up.", objectives = "Gwen Armstead wants you to investigate the Queen's Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14318] = { id = 14318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delicate Negotiations", description = "There is but one way to win the trust and loyalty of the Magram.\n\nIt must be beaten out of them.\n\nThey have suffered many losses in their war against my clan. They now possess an unfamiliar land, where they struggle just to feed themselves.\n\nNow is the time to strike.\n\nSpeak to me when you are ready, then ride in and plant my spear in the Fatherstone. If we can kill enough of them, their Khan will submit to our will.", progress = "What do you want?", completion = "Why is it that you meddle in centaur affairs, {race}?", objectives = "Khan Leh'prah wants you to place the Spear of the Kolkar Khan in the Fatherstone and defend it from the Magram until Khan Kammah appears.\n\nSpeak to Khan Leh'prah when you are ready to ride to the battle site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14319] = { id = 14319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Treatment", description = "Listen, {name}.  I'm not going to beat around the bush.\n\nThere's a good chance the potion Krennan made for you wasn't a complete success.  Or perhaps you need more of it.\n\nEither way, he's probably better equipped to advise you than I am.  Go see him.", sourceObjective = "Speak to Krennan Aranas in Duskhaven.Listen, {name}. I'm not going to beat around the bush.\n\nThere's a good chance the potion Krennan made for you wasn't a complete success. Or perhaps you need more of it.\n\nEither way, he's probably better equipped to advise you than I am. Go see him.", sourceObjectiveStatus = "unverified-source-field" }
quests[14320] = { id = 14320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Need of Ingredients", description = "Ah, yes.  The effects of the Curse cannot ever be fully cured as far as we know.\n\nWith treatment, however, your mind will remain yours... and not that of a wild animal.\n\nWe are fortunate that the treatment worked on you.  Normally, I can only treat recent infections.\n\nWe'll need to continue your medication if we're to have you reverse the Curse.\n\nI will need mandrake essence to brew another batch of my serum for you.  You will find a crate stashed beneath a shed southwest of town.", completion = "The crate has been smashed and the vials inside of it appear to have been broken.", objectives = "Find the Crate of Mandrake Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14321] = { id = 14321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion", description = "<A long knife with a skull ornament on its hilt sticks out of the militiaman's ribs.  As you look around for clues, you spot a pair of savage-looking warships at the shore.>\n\n<Gilneas is being invaded.  Bring word back to Duskhaven's Mayor, Gwen Armstead.>", completion = "Forsaken!  Quick, {name}!  We must mount a defense.", objectives = "Speak to Gwen Armstead in Duskhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14322] = { id = 14322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Science! Bad!", description = "I was trying to domesticate the indigenous hippogryphs here using a series of debilitating electrical shocks, when for some reason they went berserk! Now my test subjects are tearing up this place for no good reason! {class}, go slaughter my failed experiments before they find me.", completion = "So the world is safe for science again? Excellent! Next time I'll try heated needles or something.", objectives = "Kill 8 Static-Charged Hippogryphs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14323] = { id = 14323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absorbent", description = "One other thing I need. Hot water.\n\nNot easy around here. Not hot springs, no friends to share. One good way though. Have this sponge... it's ultra absorbent! Use it to go soak Vile Splashes at the sandbar eastish.\n\nWith enough, go squeeze them out over near the tower to summon jumbo elemental. He has hot water.", progress = "The Azshari Sea Sponge undulates with living water.", completion = "You've collected all of the simmering water droplets that Ergll requested. Now it's just a matter of summoning the \"jumbo\" elemental.", objectives = "Collect 20 Simmering Water Droplets from the Vile Splashes east of the Ruins of Arkkoran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14324] = { id = 14324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full of Hot Water", description = "Ergll indicated that you should be able to use the Engorged Azshara Sea Sponge to summon a \"jumbo\" elemental near the Tower of Eldara to the northeast.", progress = "You're back!", completion = "Convenient, no? Who needs hot springs anyway. This is perfect.", objectives = "Obtain a Globe of Boiling Water from a Scalding Water Lord at the Tower of Eldara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14325] = { id = 14325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will Work For Food", description = "<Khan Kammah listens as you explain the demonic threat, and Khan Leh'prah's visions.>\n\nNo one need lecture us about the demons, {race}. It is they who drove our clan from our ancestral lands.\n\nIt is they who forced us to take over the Kolkar wastelands, where we struggle just to exist.\n\nThe war against the Kolkar took a heavy toll on my people. What few of us remain are weary and hungry.\n\nBring food for my people and then we shall discuss the demons.", progress = "Have you brought food for my clan, {race}?", completion = "Very good, {race}.\n\nThis will sustain us for now.", objectives = "Collect 5 Basilisk Flanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14326] = { id = 14326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me Up Top", description = "I never thought that I would be a prisoner of the Alliance again. I cannot begin to express my gratitude to you... {name}, is it?\n\nI will meet you up top and from there we will deal with them.", completion = "My mission is too critical to let these meddlers continue to dog us. It's up to you and I to put an end to this once and for all!", objectives = "Make your way up top on the upper deck of the Vengeance Wake off the shore of the Lost Isles and speak with Thrall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14327] = { id = 14327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Word is My Bond", description = "It would seem that we have no choice.\n\nAs reluctant as I am to cooperate with the Kolkar, there is wisdom in the words of their Khan.\n\nYou may give him my word that we shall lend our spears to the battle.", completion = "You have done well, {class}.\n\nNow we must convince the Gelkis...", objectives = "Khan Kammah wants you to speak to Khan Leh'prah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14328] = { id = 14328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Princes", description = "The Gelkis reside in southwest Desolace. They are just as stubborn as the Magram, and since they have not suffered war and relocation, they are considerably stronger.\n\nHumbling the Gelkis will require an extreme show of force.\n\nKhan Shodo and his three sons rule the clan. Shodo is aging, and suffers from old war wounds. He never leaves the depths of his cave. The strength of his rule lies in his sons.\n\nSlay them, and persuade the Khan to commit to our cause.", completion = "My sons all slain... my clan in ruins....\n\nWere I in my youth, I would tear you limb from limb!\n\nGo now... kill me or leave me to mourn alone, {race}.", objectives = "Slay Rhoho, Sherik, and Jorreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14329] = { id = 14329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not So Fast!", description = "<The Khan of the Gelkis clan stares at you with an empty gaze as you detail the demon threat and Leh'prah's visions.>\n\nIt matters not to me what becomes of this land now. I have failed my clan and my forefathers....\n\nThere is but one thing left in this world that might bring my old soul hope, and she's likely dead as well.\n\nMy precious daughter, Kherrah, was taken from me by the Maraudine clan. If you can bring her back to me alive, I shall consider your proposal.", completion = "As you slaughter their enemy, the Gelkis clan cannot help but to acknowledge your prowess.", objectives = "Khan Shodo wants you to kill 10 Maraudine Maulers in the Valley of Spears.\n\nYou are to search their corpses for clues to Kherrah's whereabouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14330] = { id = 14330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Closed Doors", description = "You've discovered the location of Khan Shodo's daughter, Kherrah. She is being held behind the doors to Maraudon!\n\nThe rescue attempt is certain to be risky, but if you seek the Gelkis clan's cooperation, you must free the Khan's daughter.", completion = "Is it safe for me to leave, {race}?", objectives = "You are to find Kherrah somewhere behind the doors to Maraudon.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14332] = { id = 14332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time For Change", description = "<Kherrah listens to you as you explain recent events.>\n\nI agree with the words of the Kolkar Khan. The time for ancient grudges is over. It is a shame that it has taken a demonic crisis to unite the tribes.\n\nI shall return to my father and convince him to join your cause. You have my word that he will comply.\n\nReturn to Khan Leh'prah and inform him that the Gelkis will be ready when called upon.", completion = "You have done well, {race}.\n\nAnd not a moment too soon....", objectives = "Kherrah wants you to speak with Khan Leh'prah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14333] = { id = 14333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While You're Here", description = "The Maraudine have raided the Gelkis camps for many years, stealing anything they could get their hands on.\n\nOne of their favorite torments is to take these relics of power which the Gelkis hold sacred, and bring them here to be defiled.\n\nThe Gelkis clan would certainly be grateful if you were to find and destroy these defiled artifacts.", completion = "The destruction of those defiled relics will ease the minds of the Gelkis, and will strengthen their resolve.\n\nYou have done well.", objectives = "You are to scour the Valley of Spears to find 6 Defiled Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14334] = { id = 14334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blubbergut", description = "Ahoy, mon!\n\nYou think you be able ta do something for da village here?\n\nMost whales we can handle fine, but there be a special whale out there that be too big for our spears.\n\nBlubbergut been gettin' bigger an' bigger - eatin' up the fish we use to live on!\n\nGet out there and find the thing, then make him pay for his gluttony!", completion = "Oy, mon! Ya did it!\n\nWe soon be havin' fish to eat, thanks be to you.", objectives = "Mai'Lahii wants you to kill Blubbergut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14335] = { id = 14335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chipping In", description = "As you have no doubt noticed by now, the recent changes to the land have had many side-effects. Some of these are beneficial, while others pose serious problems.\n\nJust south of the village the local lobstrok are emerging from the sea and choking off the road to the village.\n\nPlease, {class}, go and thin the numbers of this pest.", progress = "Has our lobstrok problem been dealt with, {class}?", completion = "On behalf of us all at Shadowprey Village, I thank you, {race}.", objectives = "Kill 5 Drysnap Crawlers and 5 Drysnap Pincers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14336] = { id = 14336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill or Be Killed", description = "The reefs have always protected us from a coastal attack.  The earthquakes must've opened a passage for the Forsaken ships.\n\nQuick, {name}.  Slow down the attackers while I get the rest of the militia ready.\n\nI think I can hear the Prince and some of our men engaging the Forsaken even as we speak.  Speak to Liam and see how you can be of use.\n\nOh... and make sure he doesn't get himself killed.  I'm afraid he might be a little reckless in his current state.", completion = "{name}!!!  You ARE alive!\n\nI thought I was having dreams about the old days when I heard your voice...", objectives = "Speak to Prince Liam Greymane outside of Duskhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14337] = { id = 14337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowprey Village", description = "Hello again, {class}.\n\nI have received news that Shadowprey Village is in need of some assistance. Our hands are more than full here, so I must call upon you to travel there and be of assistance to them.\n\nThe village lies on the coast to the southwest of here. When you arrive, seek out the one named Mai'Lahii.", completion = "Welcome to Shadowprey Village, {race}.\n\nI was not sure the Cenarion Circle would send anyone.", objectives = "Karnum Marshweaver wants you to speak with Mai'Lahii.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14338] = { id = 14338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghost Walker Post", description = "Greetings, {class}.\n\nIt is good to see that you still draw breath. The time has come for me to call upon your services.\n\nJust southwest of this glade stands Ghost Walker Post. There you will find a forsaken by the name of Maurin Bonesplitter.\n\nHe may have a solution for one of the problems we face here.\n\nSpeak with him and do what you can to assist him.", completion = "Greetings, {class}.\n\nIt is good that you have finally arrived....", objectives = "Karnum Marshweaver wants you to speak with Maurin Bonesplitter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14339] = { id = 14339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery Device", description = "As fate would have it, there's a special deed that needs doing - one that will benefit the Cenarion Circle as well as myself.\n\nYou see, {class}, I am under pressure to create a special... concoction, shall we say. I believe my work to be complete, but I need to have it tested to be certain.\n\nThe target of this test is to be the naga, who threaten this region from the west. Their demise would surely aid the Circle.\n\nFirst though, I need a delivery device. Hollow horns from the dying kodo should do nicely.", progress = "Back so soon, {class}?", completion = "Yes, yes.\n\nThese will do nicely....", objectives = "Maurin Bonesplitter wants you to collect 3 Hollow Kodo Horns from Dying Kodo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14340] = { id = 14340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressed to Impress", description = "Every man's got to learn his own lessons I suppose.\n\nHere, take my wizard hat. I have no doubt that he'll take you on as an apprentice if you look the role... you just might have to jump through some hoops first. Tiny flaming hoops, suspended over spikes, with spinning blades on the other side.\n\nYou should be able to find an image of Xylem on top of that hill to the northeast.", progress = "Hello.", completion = "Well look at you, aren't you just a marvel of modern Magery! Quite a fancy hat, I must say.\n\nApprentices. Apprentici? I do think that I might have quite a few already, but I suppose one can never have too many appren..tici.", objectives = "Put on your new wizard hat and then speak to the Image of Archmage Xylem just northeast of the Northern Rocketway Exchange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14341] = { id = 14341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smeed's Harnesses", description = "Pardon me, young {race}.\n\nI'm in need of a little help. I've just finished filling an order for harnesses that must be delivered right away.\n\nI'm a bit old for the trip, especially considering how dangerous things have become lately.\n\nWould you mind?\n\nThey need to go to Smeed, a goblin who lives just southeast of here.", completion = "Ahh, my harnesses!\n\nThanks, friend!", objectives = "Nataka at Ghost Walker Post wants you to deliver Smeed's Harnesses to Smeed.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14342] = { id = 14342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernal Encroachment", description = "The demons are on the move, {race}!\n\nIf nothing is done, we'll be overrun in a matter of weeks. I've just returned from Mannoroc Coven, where the infernals there are falling from the sky!\n\nWe need to at least buy ourselves some time. Get down there and pick up where I left off!", completion = "Well done, {race}!\n\nThe danger persists, but you have bought us some time.", objectives = "Felgur Twocuts wants you to destroy 10 Lesser Infernals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14343] = { id = 14343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maurin's Concoction", description = "<Maurin carefully seals his concoction into the hollow kodo horns.>\n\nHere you are, {class}.\n\nBring these to Karnum. It's up to him how he wants to use them on the naga. \n\nI'll be watching to gauge the effectiveness of my formula!", completion = "I hate to use such unnatural measures, but I fear we simply have no choice....", objectives = "Maurin wants you to deliver Maurin's Concoction to Karnum at Karnum's Grove.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14344] = { id = 14344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jugkar's Undoing", description = "You recognize this as the essence of a summoned demon.\n\nDangerous and rarely understood energies weave in and out of its surface.\n\nAs you gaze upon it, a vision fills your mind - an image of yourself controlling demonic minions. A rush of excitement flows through you as you imagine wielding such power.\n\nLooking at your surroundings, you wonder how this treasure might be used against this demonic enemy....", completion = "You should be proud of how you manipulated the enemy's power and used it against them.\n\nYou've dealt the demons of Mannoroc a severe blow....", objectives = "You are to use the Infernal Power Core to take control of Lord Azrethoc at Jugkar's Altar, and use its powers to slay Jugkar Grim'rod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14345] = { id = 14345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wash Out", description = "Delicious!\n\nAzy always trying to get his hands on magic artifacts. Said he was trying to make friends with that archmage person. Xylem!\n\nXylem has LOTS of apprentices. Takes in all kinds, burns'm out, leaves them wandering all over. High turnover.\n\nLast one was last night. Headed over towards that big goblin tower construction thing, way west. Maybe he'll help you meet Xylem? Maybe Xylem knows where Azy is?\n\nPlay nice!", completion = "Look buddy, I was in your shoes not a week ago. Big powerful Archmage actually takes on apprentices! Who could pass up an opportunity like that?!\n\nSometimes, things really are just too good to be true.", objectives = "Speak to Sorata Firespinner at the Northern Rocketway Exchange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14346] = { id = 14346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Our Crevasse", description = "As you of course know, {name}, the naga remain a serious threat to the region. The time has come for us to drive them back into the sea!\n\nWhen you are ready, Grimfeather will take you to the crevasse where they are preparing a violent assault. Once there, use Maurin's Concoction to teach them a lesson they shall not soon forget.", progress = "Have you dealt with the naga in our crevasse, {name}?", completion = "Your deeds continue to impress me, {name}.\n\nPlease accept this gift on behalf of the Cenarion Circle.", objectives = "Karnum Marshweaver wants you to use Maurin's Concoction to kill 10 Slitherblade Invaders, 10 Slitherblade Sirens, and 3 Sea Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14347] = { id = 14347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hold the Line", description = "{name}!  I'm still not sure if you're alive or dead... human or worgen...\n\nI'm not even sure if I'm really awake.  But THIS I am sure of...\n\nWe're going to kill a great many of these motherless Forsaken.", completion = "Yes, {name}!  Just like old times...\n\nI'm going to have to work hard at not shooting you, but Krennan explained everything to us.", objectives = "Kill 10 Forsaken Invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14348] = { id = 14348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can't Take 'Em Alone", description = "Look here, {name}.  The big fat ones -- abominations, they're called -- they don't go down easy, so don't tackle them on your own.\n\nBut I have an idea so crazy it might just work.  Or it might get you killed, if we're not careful, I suppose.\n\nThere's barrels of gunpowder beneath the sheds and by the windmills.  Grab them and toss 'em right on the abominations' heads.  I'll take care of the rest with this trusty old blunderbuss.", progress = "They just keep coming, don't they?", completion = "You and me, {name}.  We make a great team...\n\nIt's good to have you back.", objectives = "Use the Black Gunpowder Kegs to blow up 4 Horrid Abominations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14349] = { id = 14349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call to Command", description = "The order has come down, {class}. Sylvanas herself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation.\n\nUnfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff.\n\n<Nathanos stares coldly at you.>\n\nTravel to the Undercity at once and report to the Dark Lady. Do not embarrass me, {class}!", sourceObjective = "Travel to the Undercity and speak with Lady Sylvanas Windrunner.", completion = "The Grand Crusader sits safely in the Scarlet Bastion while his forces pour into our lands, desecrate our structures and monuments and murder our people.\n\nThe time has come to deal with this pest. You will become the instrument of our reckoning.", sourceObjectiveStatus = "unverified-source-field" }
quests[14350] = { id = 14350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crimson Courier", description = "We cannot attack the Scarlet Crusade's command directly; they are too well defended. But there's more than one way to skin a cat. They'll be nothing without their main force.\n\nThe Deathstalkers have been collecting data on the activity of the Crusade outside of Stratholme. Each day, a report is sent from their central command to Tyr's Hand. This report is the key, {race}! Find the Crimson Courier and recover that report. Bring it to Nathanos.", progress = "Succeed now and you will have almost earned my respect, {class}.", completion = "<Nathanos laughs.>\n\nExcellent! Finally! An opportunity to destroy the Scarlet Oracle!", objectives = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.\n\nTake the command to Nathanos Blightcaller for further instruction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14351] = { id = 14351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Hillsbrad", description = "Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.\n\nTake this sealed commendation to Bragor Bloodfist in the Undercity.  Go with pride, {class}.", progress = "Why aren't you out on the battlefield, {class}?", completion = "So you're the {class} who tore through the Alliance forces in the Hillsbrad Foothills? I've heard your name already. Word travels fast.\n\nThe Horde can use someone like you if you keep this up, {name}.\n\nWe need to keep our eyes on all threats around us, but with that king leading them, the humans will continue to be a problem. You've confirmed that there's strength enough in the Horde to end that threat in time.", objectives = "Take Darthalia's Sealed Commendation to Bragor Bloodfist in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14352] = { id = 14352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unholy Alliance", description = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin", progress = "What do you want, {name}? This had better be important.", completion = "I've seen the insignia on this scroll before during my time in Northrend. You say this was on that crone who leads the pigs in Razorfen Kraul?\n\nI'll be damned if I'm going to let the Scourge get a foothold here. The one who wrote this - this Malcin - is one of the Lich King's servants, obviously, and that makes him a target. Your target.\n\nThey're not going to take Kalimdor.", objectives = "Take the Small Scroll to Bragor Bloodfist in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14353] = { id = 14353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unholy Alliance", description = "Supposedly this Malcin is outside Razorfen Downs. There's no question - he has to die.\n\nMy contacts in Orgrimmar tell me their scouts have found signs of the Plague down there. The quilboar are showing signs of being plagued, too; they're much more powerful. Whatever the Scourge are doing down there needs to end. Now.\n\nFind this Malcin and kill him. Report back here when he's dead.", progress = "Did you find the Ambassador, {name}? Did you kill him?\n\nI will not have the Scourge gain a foothold in Kalimdor. We've fought too hard to allow them easy access to our cities.\n\nAt least their crone still numbers among the living. She might be stupid enough to allow the Scourge in her home, but she must have sense enough to know she'd lose everything if she took the 'power' they offer.", completion = "Good work, {class}!\n\nYou've done the Horde proud by stopping the Scourge from setting down roots on our soil. An act like that deserves a reward, and the Forsaken have enough lying around that I'm sure they can spare a few things.\n\nWe may not know everything they've done in the Downs, but we'll find out. They can't slink around in the dark forever.", objectives = "Bring Ambassador Malcin's Head to Bragor Bloodfist in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14354] = { id = 14354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Gifts", description = "Simply intolerable!\n\nSatyrs of all things, desecrating our sacred lands...\n\nTheir days are numbered, {race}. I can assure you of that. As soon as we have the numbers, I shall lead a charge that will rid this land of the wicked creatures.\n\nFor now, though, perhaps you could put my mind at ease?\n\nTravel just east of here to Sargeron and scour the ruins. Find the relics of Elune and ensure that they are in good condition.\n\nI'll pay you well for this favor.", completion = "The relics are intact! Well, indeed, that is something.\n\nYou have put my mind at ease, {race}. Please accept this as my gift to you.", objectives = "Visit Elune's Relics in Sargeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14355] = { id = 14355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Scarlet Monastery", description = "One of my duties while I'm stationed here is to help the Forsaken take care of their borders, and that, {class}, is exactly what you're going to do for me.\n\nI might live and breathe, but the Scarlet Crusade will cut down my people as quickly as they will one of the undead. They're a problem here, a big one, and you're going to do something about it.\n\nGo to the Monastery and slay High Inquisitor Whitemane and her lieutenants.", completion = "I'm sure Sylvanas will be glad to have that problem taken care of, {name}. The task I gave you wasn't easy, but here you stand, victorious. That commands respect, and what you've done won't be forgotten.", objectives = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Bragor Bloodfist in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14356] = { id = 14356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power to Destroy...", description = "Listen up, {class}.\n\nYou may not know this, but Orgrimmar's got a problem. Deep in Ragefire Chasm, a sect of the Shadow Council called the Searing Blade performs their sinister work. They're mainly orcs, and I can't trust sensitive information in the hands of the grunts there. That's where you come in.\n\nThey should have two books in their possession. I want them kept out of the hands of the Searing Blade and the Forsaken alike. Bring them to me directly.", progress = "Did you secure the books? They need to be kept out of the wrong hands.", completion = "Good, {class}. You've done well. I'll keep these safe from prying eyes; the last thing we need is a strong Shadow Council rising up again.\n\nCheck back with me in the future; there's always something that needs doing around here, apparently, and I might need another able body.", objectives = "Bring the books Spells of Shadow and Incantations from the Nether to Bragor Bloodfist in Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14357] = { id = 14357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Hilt!", description = "The handmaiden of Elune! It's even more glorious than the stories tell.\n\nThe legends surrounding this relic come to your mind as you draw near it:\n\nIn ancient time, after battle, the enemies' weapons were to be cast upon the basin in exchange for a divine gift of some sort.\n\nAs you ponder this ritual, the glint of steel catches your eye from a nearby weapon rack....", progress = "The statue stands expectantly.", completion = "With the ritual completed, you are awarded a divine gift.\n\nYou can't help but to feel a great sense of honor as you receive one of Elune's boons.", objectives = "Collect 20 Satyr Sabers from the weapon racks and various satyrs in the region.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14358] = { id = 14358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Pounds of Flesh", description = "According to ancient legend, this ancient brazier was placed here for the performing of sacrifices.\n\nFrom what little you remember of the stories, a blessing is bestowed upon the being who places the flesh of Elune's enemies on the brazier's burning embers.\n\nLooking around, you determine that the satyrs who now possess this region would likely qualify.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier graciously endows you with a blessing.", objectives = "Collect 10 pieces of Satyr Flesh from the various satyrs in Sargeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14359] = { id = 14359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings From Above", description = "You feel a deep connection to the distant past having partaken of the ancient blessing granted by this relic.\n\nYou determine to make as much as you can of this divine gift.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier graciously endows you with a blessing.", objectives = "You are to collect 10 pieces of Satyr Flesh from the various Satyrs in Sargeron, and place them on Elune's Brazier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14360] = { id = 14360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing a Couple of Melons Won't Fix", description = "The markings on the Sargeron ruins, combined with what you've gleaned from Furien's text make one thing clear:\n\nThere is something special about the old fountain in the Sanctuary of Elune.\n\nIt would seem that one could expect special power from washing their face in the fountain. First, of course, there would need to be something in the ancient fountain with which to wash.\n\nPondering this problem, you spot a melonfruit at the base of a nearby tree....", completion = "After filling it with liquid from the melons, you proceed to wash your eyes from the ancient font.\n\nUpon opening your eyes, you are able to see the spirits of ancient elves, still faithfully carrying out rituals to their goddess.\n\nYou ponder the significance of this revelation and determine to study Furien's research for more clues....", objectives = "You must gather 8 Melonfruit and squeeze their juices into the Cup of Elune at Sargeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14361] = { id = 14361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace of Mind", description = "We are a forward post, charged with monitoring potential adversaries. Once the Alliance launches its Desolace campaign, our work here will ensure that there are no surprises.\n\nRecently, one of our scouts was caught and sacrificed by the Burning Blade at their stronghold to the west. Since then, we've been assaulted with threats and taunts from a Burning Blade wretch named Kohor.\n\nTheir days here are numbered, but I will pay handsomely for that one to be silenced now!", completion = "It is done.\n\nCaptain Pentigast should be able to sleep in peace now that Kohor's threats have been silenced.", objectives = "Kill Kohor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14362] = { id = 14362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears Are Burning", description = "Captain Pentigast has made no secret of his disdain for the Burning Blade at Thunder Axe Fortress.\n\nSurely, proof of their demise would be of value to him.", progress = "What have you there, {class}?", completion = "Ears of the Burning Blade?\n\n<Captain Pentigast smiles.>\n\nWell done, {class}. This is just a shadow of what will soon become of that vile cult!", objectives = "Collect 25 Burning Blade Ears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14363] = { id = 14363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Know It When You See It", description = "With his dying breath, Kohor mentioned the summoning of a demon that could threaten the entire region.\n\nHe may have been bluffing, but that's not a chance worth taking.\n\nThis cannot wait for the Alliance's invasion of Desolace to take shape. You must scour Thunder Axe Fortress for clues and bring an end to this potential threat.", progress = "The Burning Blade must not be allowed to succeed with their plan!", completion = "It is most fortunate that you took the time to search for this.\n\nNo one would have expected the Burning Blade to be in possession of something so powerful!", objectives = "Find the Ancient Summoning Ritual in Thunder Axe Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14364] = { id = 14364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Their Heads Together", description = "So it's true....\n\nThe parchment you discovered in Thunder Axe Fortress details a powerful summoning ritual. One stronger than the Burning Blade have ever been known to possess.\n\nClearly, this rite must be stopped at all costs!\n\nPerhaps if this demon were summoned forth prematurely the crisis could be averted.", completion = "You diverted what would have been a serious crisis, {class}.\n\nIf that summoning was delayed just a bit longer, the demon would have become far too powerful for our small forces here to contend with.\n\nPlease accept this gift as our thanks for your service.", objectives = "Collect 100 Bleached Skulls from Thunder Axe Fortress, then place them at the Burning Blade Summoning Circle, then kill Nazargen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14365] = { id = 14365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethel Rethor", description = "We have recently received a plea for help from a researcher of the Cenarion Circle.\n\nWe have no one we can spare to send, so I ask that you pay her a visit on our behalf.\n\nKorrah is posted near the ruined tower of Ethel Rethor, on the coast to the west.", completion = "It is good that you have come.\n\nThere is grave danger looming here.", objectives = "Corporal Melkins wants you to speak to Korrah at Ethel Rethor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14366] = { id = 14366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holding Steady", description = "We can take it from here, {name}.  Check in with Mayor Armstead.\n\nThese are only a small part of the Forsaken's forces.  If we don't move quickly we're going to have bigger problems on our hands.\n\nSee what you can do to engage the Forsaken army at their landing location.", completion = "Great news, {name}.  I've sent the remaining militia to the shore to meet the Forsaken force head on.", objectives = "Speak to Gwen Armstead in Duskhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14367] = { id = 14367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Allens' Storm Cellar", description = "Lord Godfrey is leading the attack near the Forsaken's landing area.  See what you can do to help us keep the Forsaken back.\n\nI've been told Godfrey has commandeered the storm cellar in the Allen Farmstead, far to the west.  Seek him there.", completion = "The Forsaken are here in full strength, {name}.  We barely have enough men to hold them back.", objectives = "Speak to Lord Godfrey inside the storm cellar of the Allen Farmstead in Gilneas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14368] = { id = 14368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Children!", description = "The military will not allow me outside the cellar, but my children are still in my farm!  Please, you must go find them.\n\nThe Forsaken have no regard for innocent life -- my kids are in great danger!\n\nTheir names are Cynthia, Ashley and James.  If you find them, bring them back here.  I'll be forever in your debt.", progress = "I... I don't know if I can go on without them.", completion = "My children are safe!  You've done a wonderful thing, {name}.  I don't know how to thank you!", objectives = "Rescue Cynthia, Ashley and James in the Hammond Farmstead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14369] = { id = 14369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash the Beast", description = "I'm not going to lie, {name}.  I don't like the idea of having worgen among our ranks.\n\nWho knows how long 'til Krennan's concoction wears off and you're trying to chomp one of our heads off.\n\nUntil that time, however, we can make ample use of your ferocity.\n\nI want you to go out in the battlefield and kill as many of those Forsaken as you can, in as brutal a way as you can.\n\nWe're going to put the fear of the worgen in them, {name}.", completion = "Not bad, {name}.  It's a good thing you're on our side.", objectives = "Kill 8 Forsaken Footsoldiers or Sailors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14370] = { id = 14370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Azsharite", description = "Azsharite! This mysterious crystalline substance has been used to forge weapons of fel power, but in our hands, we've discovered that it's capable of focusing enormous amounts of energy. It may be the biggest goblin discovery since kaja'mite.\n\nBut what is it? Where does it come from? Why is it located only here? Science demands an answer! I need more samples to study. Search out Azsharite deposits all along the nearby cliffs.", progress = "Have you got more samples? Careless adventurers have been looting this stuff for years - they don't know how precious it is!", completion = "Ah, excellent. Some of these samples look fresh. I'm going to be up to my neck in this stuff trying to solve this mystery!", objectives = "Collect 5 Azsharite Samples from the nearby cliffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14371] = { id = 14371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gigantic Snack", description = "While you're here running around the cliffs, perhaps you can help me with another line of investigation. The giants who walk these cliffs have been here since these mountains formed. Maybe they know where the Azsharite comes from? It's in our best interest to befriend these giants and find out.\n\nGather up a gigantic meal for me as a peace offering! Kill the mistwing cliffdwellers that have been such a nuisance to our studies and collect their carcasses for me.", progress = "I probably should've warned you that mistwing chimaeras can shoot lightning.", completion = "Phew! The stench! Well, hopefully that massive heap of carcasses smells more appetizing to a giant.", objectives = "Collect 8 Mutilated Mistwing Carcasses from Mistwing Cliffdwellers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14372] = { id = 14372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thargad's Camp", description = "It pleases me to see that you still draw breath, {class}. I have been sent word that the demon activity in the south has been intensifying.\n\nThere is a camp on the borderlands there that is in danger of being cut off if the demons move northward.\n\nPerhaps you could lend them a hand?\n\nI know the leader of the camp there is Thargad. He will be able to direct you wisely.\n\nThank you, friend. Be well.", completion = "Demons?\n\nOh, there be lots I can tell yeh 'bout demons!", objectives = "Karnum Marshweaver wants you to speak to Thargad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14373] = { id = 14373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernal Encroachment", description = "Listen up, now. An' lookie here.\n\n<Thargad points off to the east.>\n\nYeh see them big green glowin' balls that be fallin' from the sky?\n\nThose be a nasty buncha demons roamin' the lands unchecked. Well, almost unchecked... I've been keepin' 'em on their toes, givin' 'em sumthin' ta think about.\n\nHow 'bout you get over there an' pick up where I left off?", completion = "Well, lad!\n\nDon't hesitate to knock a few more down for good measure!", objectives = "Destroy 10 Lesser Infernals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14374] = { id = 14374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portals of the Legion", description = "Here it is - the Hand of Iruxos.\n\nGot it from one o' them Burning Blade leaders myself.\n\nPowerful thing! See, yeh use it on demon portals and they just disappear! Spooky magic, but these be desperate times...\n\nThe demons keep comin' at this rate, and my camp will get overrun before ya know it.\n\nHere ya go, now. Get on with it.", completion = "Aye, that'll buy us some time, {class}.\n\nThank yeh.", objectives = "Banish 6 Portals at Mannoroc Coven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14375] = { id = 14375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Chance at Humanity", objectives = "I need you to pull through, {name}.  This dosage is strong enough to kill a horse.\n\nBut I know you.  I know what you're made of.  You will be fine.\n\nTrust me.  I know what you're going through.\n\nNow drink up and close your eyes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14376] = { id = 14376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jugkar's Undoing", description = "You recognize this as the essence of a summoned demon.\n\nDangerous and rarely understood energies weave in and out of its surface.\n\nAs you gaze upon it, a vision fills your mind - an image of yourself controlling demonic minions. A rush of excitement flows through you as you imagine wielding such power.\n\nLooking at your surroundings, you wonder how this treasure might be used against this demonic enemy....", completion = "You should be proud of how you manipulated the enemy's power and used it against them.\n\nYou've dealt the demons of Mannoroc a severe blow....", objectives = "You are to use the Infernal Power Core to take control of Lord Azrethoc at Jugkar's Altar, and use its powers to slay Jugkar Grim'rod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14377] = { id = 14377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befriending Giants", description = "A cursory study of the azsharite you brought me reveals that it's not biological in nature, nor is it naturally formed. There's another creature in Azshara with similar properties: the cliff giants that lumber around these cliffs.\n\nOne of the giants seems willing to help our research along. Take the meat you collected to Gormungan, the giant standing just west of here. Befriend him, then grill him - find out if he knows the secret of azsharite!", progress = "What did you discover? You look pale, {class}!", completion = "Speak slower - what are you saying? Am I hearing you right? Those formations of azsharite are actually where the giants have - oh my. Groady!! Let's not tell Dr. Grapplehammer, he's made this stuff his life's work.\n\nWell, at least now we know where azsharite comes from, and why it's so rare. We've got to figure out a way to speed up, uh, \"production!\"", objectives = "Talk to Gormungan outside of the Southern Rocketway Terminus and discover the secret of azsharite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14378] = { id = 14378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Brendol", description = "I'm too busy collectin' artifacts to busy myself with much else, but there is a bit of an issue here I wouldn't mind sortin' out.\n\nThere's a forsaken apothecary who's been pokin' around these parts for a while now. Normally, I'd ignore him, but three times now he's snuck into my camp and pilfered my supplies.... enough's enough!\n\nFind the thief and bring me whatever's left o' my things!", progress = "Well, {class}? Did yeh find the cretin?", completion = "Justice is done!\n\nNow let's have a peek at what's left of my goods....", objectives = "Recover Brendol's Satchel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14379] = { id = 14379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Lobstrock!", description = "Thargad works practically nonstop chasing after ancient Titan relics. He stays so busy that if it weren't for me, he'd probably forget to eat!\n\nSpeaking of eating, I'd like to prepare him something special - perhaps you could help me out?\n\nLobstrock roam all over the coast to the west. I'd never last in a fight with them myself, but I could make a great meal if you were to bring me some of their tails!", progress = "Were you able to collect some lobstrock tails, {race}?", completion = "Ohhh, these will do nicely!\n\nThargad will be so surprised!", objectives = "Get 7 Tender Lobstrock Tails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14380] = { id = 14380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Impactful Discovery", description = "<Thargad rummages through the satchel and pulls out a curious object.>\n\nWell now, this is odd... it's a hollow kodo horn with some sort of potion inside.\n\n<Thargad sniffs the potion.>\n\nWHEW! Definitely not any kind of healthy elixir. This mess is meant for one thing... killin'.\n\nHow 'bout yeh run it back up to Karnum and see if there's anything he can do with it...", completion = "<Karnum examines the concoction.>\n\nYes, {class}. Not only do I know what this is, I know just how you should use it....", objectives = "Take the Mysterious Concoction to Karnum at Karnum's Glade.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14381] = { id = 14381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Our Crevasse", description = "I recognize this foul creation. It's a terrible disease that kills almost instantly, and in a most violent manner. Loathe as I am to employ such devices, I fear we have no choice here.\n\nAs you of course know, the naga remain a serious threat to the region. The time has come for us to drive them back into the sea!\n\nWhen you are ready, Grimfeather will take you to the crevasse where they are preparing a violent assault.\n\nUse the concoction on the naga and their allies to make Desolace safe!", progress = "Have you dealt with the naga in our crevasse, {name}?", completion = "Your deeds continue to impress me, {name}.\n\nPlease accept this gift on behalf of the Cenarion Circle.", objectives = "Use Maurin's Concoction to kill 10 Slitherblade Invaders, 10 Slitherblade Sirens, and 3 Sea Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14382] = { id = 14382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two By Sea", description = "The Forsaken catapults are kicking the snot out of us, {name}.  And even if we do take care of them, they've two ships with rows of cannons at the ready.\n\nI've a plan to kill two birds with one stone.  You're the stone in this plan.\n\nTake out the machinists manning the catapults.  After this, use the catapults to launch yourself aboard the Forsaken ships.\n\nIf your aim isn't terrible, you should be able to land safely.  Once onboard, go below decks and take care of each ship's captain.  Good luck, {class}.", completion = "Well done, {name}.  You might be a bloody beast, but you're our beast.", objectives = "Use the Forsaken Catapults to board the Forsaken ships and slay Captain Morris and Captain Anson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14383] = { id = 14383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrible Tinkers of the Ruined Reaches", description = "Scoundrels! Infidels! Ever since I started my operation here in Azshara the Gadgetspring family has hampered my studies and sabotaged my research. And now a mob of middling, second-rate tinkers have rallied to their aid! I have pressing business to attend to: see to it that those gnomes are finished for good.\n\nHead to the Ruined Reaches on the coast, south of my Secret Lab, and start rolling some of their disproportionately enormous heads for me.", progress = "I trust you've dug a significant number of tiny graves along the coast, yes?", completion = "Oh - marvelous. Tell me more. And that precocious young Gadgetspring? Dead as well? Ah, wonderful. My work here is important but at times I do miss the carnage of demolishing my enemies on a more personal level. Here, perhaps you can make use of some of my discarded equipment.", objectives = "Slay Bingham Gadgetspring in the Ruined Reaches, along with 4 Netgun Gnomes and 6 Zapper Gnomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14384] = { id = 14384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rerouted!", description = "Halt!\n\nOn behalf of the Nijel's Point Guard, I am under orders to send all able-bodied allies to report directly to Corporal Melkins.\n\nI am not authorized to offer any other information.\n\nWhat I can offer is transportation. You are free to use my mount. It will deliver you directly.\n\nDismissed.", completion = "Welcome to Nijel's Point, {race}.\n\nNow, let's see about getting you briefed on our situation here.", objectives = "Officer Jankie wants you to ride her mount to Nijel's Point and speak to Corporal Melkins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14385] = { id = 14385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharite Experiment Number One", description = "Well, I can think of one surefire way to send a giant running to the bathroom, but you're not going to like it. What we need is a ... massive ... laxative. Oh hey! Would you believe the gnomes have something of the sort? That can't be a coincidence. I wonder what they're trying to push through over there?\n\nOur intelligence reports that the laxative was delivered to Gadgetspring's tower, down on the shoreline south of the Secret Lab. Retrieve that laxative and feed it to Gormungan!", progress = "Once you have the laxative, try to feed it to Gormungan. And maybe give him a magazine or something. Do it for science!", completion = "So it was a no-go? Literally? Well, Grapplehammer won't take no for an answer. We'll have to try something else.\n\nMaybe I'll have my interns smuggle this laxative into the night elf encampment. That'll be good for a laugh, at least.", objectives = "Grab a giant-sized laxative from the gnomish tower in the Ruined Reaches. Try to feed the laxative to Gormungan the giant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14386] = { id = 14386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leader of the Pack", description = "Excellent work so far, {name}.  Our scouts have identified the leader of the Forsaken ground assault.\n\nOne of Sylvanas' handpicked dark rangers is overseeing the battlefront from the Walden house near the shore.  Take this whistle and use it when you're close to her.\n\nI'll have my men let loose our attack mastiffs to take her down.  Be careful, {name}.  You don't want to engage her alone.", progress = "Is it done yet, {name}?", completion = "You did it, {name}.  That should take the wind out of their sails.", objectives = "Use the Mastiff Whistle to help you slay Dark Ranger Thyala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14387] = { id = 14387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lay of the Land", description = "Yes, yes. Welcome to Desolace, {race}.\n\nSorry we had to be so insistent, but we're a small outpost, and there are big problems in this region - most of them quite urgent.\n\nBottom line: We need all the help we can muster.\n\nTo start with, our friend Vahlarriel over there has been getting pretty antsy, insisting that we send a contingent to visit the ruins to the east.\n\nWhy don't you go introduce yourself....", completion = "A pleasure to meet you, {class}.", objectives = "Captain Pentigast wants you to speak to Vahlarriel in Nijel's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14388] = { id = 14388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharite Experiment Number Two", description = "Okay, new plan. We'll SCARE it out of 'em! In my experience most large creatures are terrified of tiny ones - like rats. Hmm. This place is crawling with rats, but how do we coax them over to the giant?\n\nHey! You don't mind having your cellular matrix broken down and reassembled do you? It's only painful while it's happening. I can shrink you down to rat-sized and you can ride one of these brutes over there like a horse. It's so crazy it's got to work! Speak with me when you're ready for shrinkage...", progress = "Hey {name}, you look shaken up. Did you scare the giant into going to the bathroom? Or yourself?", completion = "So scaring him didn't work, either? Double-nertz! I'll have to break the news to Grapplehammer: Azsharite's going to remain the rarest substance on the planet. We'll have to use it sparingly.", objectives = "Speak with Assistant Greely to be shrunken down to rat-size. Mount a Rocketway Rat and use it to terrify Gormungan the giant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14389] = { id = 14389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasn't It Obvious?", description = "Azuregos! Yes, of course. Troubled old dragon, but lovely heart. I don't think all the years of vagabonds assaulting him have done him much good. He's a mite strange these days.\n\nNot long ago, when returning yet again to our local Spirit Healer, Anara, I couldn't help but notice that her and Azuregos seemed to be hitting it off. I imagine he's still keeping her company.\n\nThe portal behind me is probably the quickest way to reach her. It might sting a little though.", completion = "Azuregos! At last you've found him!", objectives = "Use the portal behind Joanna at Xylem's tower to find Anara the Spirit Healer and--hopefully--Azuregos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14390] = { id = 14390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy is Boring", description = "After a long search with some questionable turns, you've finally found Azuregos.\n\nNow it's just a matter of convincing him to meet up with Kalecgos and put an end to the threat of the black dragonflight in Azshara.", progress = "<Azuregos glares at you.>", completion = "Azuregos has agreed to rendezvous with Kalecgos. Success!", objectives = "Convince Azuregos to return to the world of the living and rendezvous with Kalecgos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14391] = { id = 14391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Tables", description = "Azuregos and Kalecgos are due to meet up at the Northern Rocketway Terminus. You should meet with them there to make sure that Kalecgos doesn't require any additional help.\n\nShould you prefer to not be dead, Anara will likely be able to help.", completion = "Great to see you again! Thank you for finding Azuregos and sending him to me.\n\nI do feel I owe you an apology - I may have undersold how difficult it would be to accomplish the task I gave you. You performed quite admirably, {name}.", objectives = "Speak to Anara to return to the world of the living, then meet with Kalecgos at the Northern Rocketway Terminus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14392] = { id = 14392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farewell, Minnow", description = "Thank you, little one.\n\nSometimes it's easy to get lost in the throes of love and lose sight of things, even as a dragon. I plan to rededicate myself entirely to making sure Kalec never steps up to take Malygos' place. It's the most noble cause I can think of.\n\nYou should head back to the harbor. I believe someone's waiting for you there.\n\nTry not to get squashed or eaten by anything.", completion = "Hey there... again.\n\nLook, I gave you my hat. It was a gift. I thought you'd make some use of it. More specifically though, I thought you'd get it the heck away from me.\n\nCan you imagine my surprise when Xylem comes by himself to give it back to me? \"Want to be more like my other apprentices, Sorata? Give your hat another try.\"  Not one of my proudest moments.\n\nSo what... you just tossed it aside for him to find? No. I don't think so. You're going to take this hat and you're going to like it. Really.", objectives = "Speak to Sorata Firespinner in Bilgewater Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14393] = { id = 14393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Fray!", description = "For untold generations, the centaur clans have fought against one another, but no more.\n\nBecause of your deeds, we stand here together fighting a common foe. We shall win our ancestral lands back from these demons, or we shall die as brothers.\n\nWhat of you, {name}?\n\nYou have earned the right to fight alongside us. I have a group of my best centaurs for you to lead into battle.\n\nWill you take up the spear?", completion = "Well done, {name}!\n\nLet us finish this!", objectives = "Khan Leh'prah wants you to defeat 15 Burning Blade Warlocks, 3 Doomguard Invaders, and Priestess Than'darissa.\n\nSpeak to Khan Leh'prah to ride into battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14394] = { id = 14394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Agogridon", description = "Our goal is within sight, {name}!\n\nWe can break the will of this demon army by bringing down the one who leads them. If we can succeed, Desolace will be ours!\n\nWhen you are ready, lead a group of centaurs through the pass to the south, into Shadowbreak Ravine. Find where Agogridon hides!\n\nI will gather the other khans and meet you there to face him in battle.", completion = "Agogridon is no more.\n\nThe demons shall never again take hold in our lands!", objectives = "Defeat Agogridon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14395] = { id = 14395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gasping for Breath", description = "{name}!  I was on my way when it happened.\n\nNo time to waste.  A good half of the town watch was in the area that collapsed.  Get in there and save as many as you can.\n\nMake sure to get them out of the water and onto shore.  I'll make sure they get any aid they need.", progress = "There aren't many of us left, {name}.  We have to look out for those remaining Gilneans.", completion = "You did what you could, {name}.  With any luck a few others will find their way to shore.", objectives = "Rescue 4 Drowning Watchmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14396] = { id = 14396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As the Land Shatters", description = "What in the world was that, {name}?\n\nThose were not cannons or catapults, that is for sure.\n\nGo outside and see what is going on.", completion = "The ocean, {name}.  It swallowed everything... the land... the Forsaken... our men!", objectives = "Speak to Prince Liam Greymane at the Allen Farmstead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14397] = { id = 14397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuation", description = "We've escaped death through dumb luck, {name}.  But luck is running out.\n\nThe coast is becoming flooded even as we speak.  And from the look of it, the landmass beneath us hasn't quite settled yet.\n\nI hate to say this, but we have to leave.  Curses, {name}.... I cannot lose my homeland twice in one lifetime.  Yet these earthquakes are not an enemy we can defeat.\n\nTell Gwen Armstead to start the evacuation.", completion = "Liam is right.  We must get everyone to higher ground.\n\nYou must help me spread the word while I manage the logistics of the evacuation.", objectives = "Speak to Gwen Armstead in Duskhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14398] = { id = 14398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grandma Wahl", description = "It's not going to be easy to get Grandma Wahl to come with us.  You must do whatever you can to convince her, though.\n\nYou'll find her at the Wahl Cottage.  Please, {name}.  Do not lose your patience with her.  Her mind is old and she's not entirely lucid.", completion = "A visitor!  Are you staying for tea, sweetheart?", objectives = "Find Grandma Wahl at the Wahl Cottage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14399] = { id = 14399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grandma's Lost It Alright", description = "Leave?  Now?\n\nWell, if I must, then I must.  But will you be a sweetheart and find something for me?\n\nI've lost my favorite book and won't leave without it.\n\n<After you explain the gravity of the situation, Grandma Wahl shakes her head condescendingly.>\n\nDear, just find the book will you?", progress = "How goes it, dear?  Will you be staying for tea?", completion = "Why thank you, {name}.  I hope you didn't peek!\n\nWhere are your manners, dear?", objectives = "Find the Linen-Wrapped Book.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14400] = { id = 14400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Can't Wear This", description = "What was it you wanted again?\n\nOh, right.  The evacuation orders.\n\nWell I can't be expected to go out in public like this, can I?\n\nGo get me my good clothes.  They're on the clothesline right outside.\n\n<You struggle in vain to convince Grandma Wahl that what she's wearing will do.>\n\nYou young people truly have no manners.  Were you raised by ogres?  Now go get my clothes, sweetie.", progress = "Did you find everything okay, dear?", completion = "You're a peach, {name}.  Thanks!", objectives = "Get Grandma's Good Clothes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14401] = { id = 14401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grandma's Cat", description = "Right!  About the evacuation, dear.\n\nI just cannot leave without my cat.  He's an adorable orange tabby.\n\nChance's favorite spot to play is a broken down cart near an arbor northeast of here.\n\nBring him here and we'll be on our way.", progress = "You're such a charming young man, {name}.", completion = "There he is!  Grandma's special boy!\n\nThank you so much for finding him.  I hope it wasn't too much trouble.\n\nMy... what manner of dirt found its way underneath my fingernails!", objectives = "Retrieve Chance the cat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14402] = { id = 14402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready to Go", description = "I suppose now is as good a time to leave as any.\n\nI have my best outfit, my favorite book and my loving cat.\n\nI hope I'm not forgetting anything.\n\nTell that mayor of yours that I'll be on my way.  I suppose I'll see you in town with the others!", completion = "You did the impossible, {name}.  You convinced Grandma Wahl to leave her home.\n\nYou are something else, let me tell you.", objectives = "Speak to Gwen Armstead in Duskhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14403] = { id = 14403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hayward Brothers", description = "The Hayward Fishery can be found far to the south.  The Hayward brothers have been running it for years.\n\nThey don't make it to town very often, except to trade their fish.  Send word to them that the evacuation is underway.", completion = "You here to give us a hand?", objectives = "Speak to Sebastian Hayward at the Hayward Fishery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14404] = { id = 14404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Quite Shipshape", description = "Evacuation, you say?  Well, we had that very same idea all on our own after these Forsaken started showing up.\n\nWe were thinking the water would be the safest way out of here.\n\nUnfortunately our boats didn't come out from that last earthquake unscathed.\n\nI need some additional supplies to finish my repairs: wood, tar and my tools.  Get them for me so that my brothers and I can make it out of here.", progress = "Do you have my supplies, {name}?", completion = "This is great, {name}.  I should be able to finish the repairs in no time.", objectives = "Obtain Planks of Wood, Coal Tar and Shipwright's Tools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14405] = { id = 14405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape By Sea", description = "Thanks for your help, {name}.  This ship is ready to sail.\n\nNow you go and tell Miss Armstead that we're not going to be part of the land evacuation.\n\nWe Haywards have been men of the sea for generations.  If we're to leave our home, then we'll do so by sea.", completion = "It's just as well, {name}.  Maybe the Haywards will fare better than us.", objectives = "Return to Gwen Armstead in Duskhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14406] = { id = 14406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crowley Orchard", description = "Of course you remember Lord Darius Crowley's daughter, Lorna.\n\nShe never quite recovered after losing her father in Gilneas City.  She's basically led the life of a hermit.  The only visitor she's allowed into her house has been Krennan... and he won't say a word about the whole thing.\n\nSend word to her about the evacuation.", completion = "Stay back! Don't make me...\n\nIs it you?  By the Light!  It's you, {name}!", objectives = "Speak to Lorna Crowley at the Crowley Orchard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14407] = { id = 14407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azshara Blues", description = "Hey! I'm glad I caught you.\n\nI come on behalf of my master, Kalec. He requires your aid. Find him under the bridge in the slums as soon as you can!", completion = "Thank you for coming. I apologize for the discretion, but it's extremely important that I not be seen by certain individuals.\n\nI'm in quite a bind and I've taken notice of some of your recent deeds. Hear me out, help me, and I'll see to it that you're rewarded in kind.", objectives = "Meet with Kalec in Bilgewater Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14408] = { id = 14408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nine's Plan", description = "My benefactors used their diminutive intellect to construct an interplanetary transport. As designed, this so-called \"Rocket\" is a death trap. But I suspect a simple re-engineering of the fuel catalyst semifold would render a stable mixture, providing a breathable oxygen byproduct. To implement such changes, I require the original engineering plans.\n\nLocate the Laboratory Archives and ring the doorbell to gain entry. The plans will be held by the lab director himself, presuming he still lives.", progress = "I suspect the archives are close, {name}. Locate those plans!", completion = "<The raptor snatches the paperwork in her prehensile claws and holds the schematics up to her face, clucking her pointed teeth dismissively.>\n\nThese are like the scrawling of children. Common sense precludes the routing of control hydraulics so near to the secondary stage burners! Still, this is salvageable.\n\nDo you know how to refactor fuel matrixes for pressure variations at a fixed acceleration? No? Very well, perhaps you can do something else for me while I reconfigure the rocket...", objectives = "Acquire the Secret Rocket Plans from the Laboratory Archives building at the eastern end of the Secret Lab. Ring the door buzzer outside and kill the lab director when he emerges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14409] = { id = 14409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cautious Return", description = "A moment of your time, {class}.\n\nChange is coming. It has drawn us out of the ruins of Eldre'Thalas and into the wide world once more. I have come to research this city and cannot stray from it, but if you are inclined, I have an errand for you.\n\nMy colleague set out for Darnassus to speak with the High Priestess there, that we might come to an understanding. Take this journal to Mordent Evenshade in the temple. It may help in his diplomacy mission.", progress = "It seems I have time to talk. What is this regarding?", completion = "Ah, the writings of Daros. He always was meticulous about tracking progress. His words may aid in explaining how far we've come.\n\nYou have my thanks for bringing this to me, {race}. Perhaps we will see more of each other once it is understood we mean no harm.", objectives = "Bring Daros' Journal to Mordent Evenshade in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14410] = { id = 14410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wilds of Feralas", description = "You are truly brave to help us protect these lands, hero. If you wish to do more for the wilds, there are others in need of your aid.\n\nThe verdant forests of Feralas lie to the south. There, in the shade of the mighty Twin Colossals, you must seek out Telaron Windflight. At Dreamer's Rest, he and his fellow druids of the talon have found signs of a disturbing illness.\n\nThey will need your help, {class}. Go in peace.", completion = "Welcome to Feralas, {class}. I thank you for coming to assist us.", objectives = "Travel to Feralas and speak with Telaron Windflight at Dreamer's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14412] = { id = 14412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Washed Up", description = "Those Forsaken ships sank way too close to our Fishery.  All the survivors are making their way here and, as you can see, we're a bit outnumbered.\n\nHelp us hold them back while I finish making repairs to the boats.", progress = "Bloody Forsaken!  Not even the ocean wants them!", completion = "Excellent!  I'm almost done here.", objectives = "Kill 6 Forsaken Castaways.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14413] = { id = 14413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pinnacle of Learning", description = "This is so exciting! What's exciting you might ask? Well THIS is of course!\n\nTime to trial... time for YOU to trial. So many challenges to overcome, so much learning to be done. You learning about trials. Me learning about you.\n\nSo now, off you go. To my Arcane Pinnacle. I will meet you there of course, because I'm quite everywhere.", completion = "Here so soon! Lovely trip I hope. Not too nauseous or anything?\n\nThere will be much running and much jumping, so a settled stomach is of great practicality.", objectives = "Speak to the Image of Archmage Xylem at the base of the Arcane Pinnacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14415] = { id = 14415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apparitions in the Orchard", description = "Listen, {name}.  I heard about what happened to you and I trust you regardless of your... affliction.  After all, you were with my father until the end.\n\nBut I'm not going to go out there.  It's not safe.\n\nThe earthquake opened a passage from the mountains and an ettin has decided to pay us a visit.\n\nNot only that, but after I holed up in the house, I started seeing ghostly wolf forms in the orchard.\n\nI can't come out until we at least have some idea about what's going on.", sourceObjective = "Investigate the Crowley Orchard.Listen, {name}. I heard about what happened to you and I trust you regardless of your... affliction. After all, you were with my father until the end.\n\nBut I'm not going to go out there. It's not safe.\n\nThe earthquake opened a passage from the mountains and an ettin has decided to pay us a visit.\n\nNot only that, but after I holed up in the house, I started seeing ghostly wolf forms in the orchard.\n\nI can't come out until we at least have some idea about what's going on.", sourceObjectiveStatus = "unverified-source-field" }
quests[14416] = { id = 14416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hungry Ettin", description = "Listen, {name}.  We're not going to make it very far without transportation, are we?\n\nIf we just hightail it out of here, the forsaken will catch up to us in no time at all.\n\nRounding up some horses from the stable grounds southeast of here would normally be a breeze, but there's one snag.\n\nThat last quake must've spooked Koroth, the ettin, down from the mountains.  If we don't get our horses soon, I fear that he will.", progress = "You're back, {name}.", completion = "We've got the horses, I'll make sure Duskhaven gets them.", objectives = "Bring 5 Mountain Horses to Lorna Crowley at the Crowley Orchard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14418] = { id = 14418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.\n\nHawkins will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.\n\nAh, and how could I forget?\n\nWelcome to the Deathstalkers.", objectives = "Deliver Andron's Ledger to Aleric Hawkins in the Hall of the Dark Lady in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14419] = { id = 14419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.\n\nOur leader suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.\n\nI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.", objectives = "Speak with Andron Gant in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14420] = { id = 14420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "If you wish to join the Deathstalkers, the Dark Lady's elite guard, you will have to prove your worth.\n\nI will not lie to you, {name}, this task could mean your death.\n\nI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.\n\nIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.", objectives = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14421] = { id = 14421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.", objectives = "Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14422] = { id = 14422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Raptor Rocket", description = "Shortly after my intellect was augmented, I bred with Subject Four in order to create a unique race of cognitively superior raptors. Subsequently, Subject Four neither called nor wrote: I have determined to disembowel him upon our next encounter.\n\nNonetheless, there are enough raptor children imprisoned in this lab to provide adequate genetic stock for repopulating my race. Please release them from their cages and carry them to the rocket.", progress = "My beautiful children may attempt to bite you upon release, but at their stage of physical development, it is unlikely that their attacks will be fatal.", completion = "Wonderful! Exemplary work, {name}! As you have no doubt surmised, my objective with regard to this rocket is to utilize it as a sort of astral cradle, an ark if you will, allowing my newly-forged race to slip the surly bonds of this ravaged planet and colonize a world to our own liking. You have been instrumental to our cause. Please accept this currency as I will be minting my own monetary units upon arrival. Farewell, {name}!", objectives = "Release five Experimental Raptors from their cages in the Secret Lab and deliver them to the rocket beside Subject Nine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14423] = { id = 14423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dozercism", description = "...what we need is a priest!\n\nFortunately I have a small budget set aside for the blessing of machinery. Take this flare gun and head over to Margene, my poor sweet busted bulldozer. Fire off the signal and one of our finest airborne priests should airdrop in to get a handle on the situation. Come back when my bulldozer is taken care of!", progress = "How is Margene doin'? Running like her sweet self again?", completion = "What? ...What?\n\nMargene! Oh my sweet Margene!!", objectives = "Use the Blessed Flare Gun near Clubnik's Dozer to summon in help, then 'Exorcise' the bulldozer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14424] = { id = 14424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need More Science", description = "<Clubnik wipes away a tear, then juts his chin out with determination.>\n\nNever again, {name}! No bulldozer deserves the fate of my Margene. We're going to need some industrial ghostproofing. This is a job for our top scientists, and I know just the woman for the job! Look for Assistant Greely at the Southern Rocketway Terminus. She's the administrator for Azshara's world-famous Secret Lab, and she owes me a favor.", completion = "What is Clubnik talking about? Haunted construction equipment? Does it look like I have time for ghost stories?\n\nI've got a laboratory in the middle of a meltdown, fires burning, animals mutated, and worst of all - projects falling behind schedule. Help!", objectives = "Locate Assistant Greely at the Southern Rocketway Terminus. The Goblin Rocketway can be used to quickly move around Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14425] = { id = 14425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Quest", description = "Greetings, {name}, this is a test.  Accept and kill stuff", objectives = "Test Thrall wants you to kill something.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14426] = { id = 14426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Quest", description = "This is the second quest!  This time you won't have to kill stuff.", objectives = "Santa Thrall wants you to collect 5 boozles, whatever those are.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14427] = { id = 14427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Item Quest", description = "Item collection quest", objectives = "Get the items", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14428] = { id = 14428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amberwind's Journal", description = "If my sources are trustworthy, Lorekeeper Amberwind is overseeing the Alliance investigation of the ruins to the east. I have not yet probed the extent of her abilities: I'm hoping you can give me a full report by engaging her in combat and destroying her.\n\nWith a title like 'Lorekeeper,' I'm guessing Amberwind will have a journal on her that'll tell us exactly what those night elves are up to. Fetch that journal for me. No need to run back; use their own scrying stones to contact me remotely.", progress = "<Andorel's distorted face appears within the scrying stone.>\n\n{name}, have you made contact? What can you tell me?", completion = "Amberwind was making use of an Arcane Construct? Hah! How delightfully inexperienced. It's like watching children play with firearms.\n\nLet's take a look at that journal, {name}. Hold it up to the scrying stone... keep it still ...", objectives = "Slay Lorekeeper Amberwind at the Darnassian Base Camp and retrieve her journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14429] = { id = 14429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane De-Construction", description = "Arcane constructs are creatures spawned of pure mana and intellect. In the right hands, a construct allows its user to quickly assimilate vast riches of arcane knowledge. But they're dangerous, {name}. So intelligent! So powerful! So very vulnerable to external tampering...\n\nLet's teach these amateurs a lesson and use their own magic against them. Slay Apprentices and collect their runestones for me. Contact me via the lower scrying stone when you're done.", progress = "<Andorel's image is blurry and indistinct. He squints at you and taps against the glass of the scrying stone.>\n\n{name}, is that you? The resolution on this stone is terrible. What kind of hardware are they using?", completion = "Good work getting those runestones. To be honest, I only needed one, but the thought of so many night elves slain for such useless baubles fills me with a dark, giddy joy.\n\nPlease hold one of those runes up to the scrying stone to let me see. Hmmm. As I suspected, an amateur effort at best.", objectives = "Slay Apprentice Investigators and Apprentice Illuminators to collect 10 Attuned Runestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14430] = { id = 14430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Construct", description = "Now we will hack their arcane construct and use it to wreak havoc. Have you done this type of magic before, {name}? No? Hah! That makes my plan all the more delicious. Nearby you should see a formidable arcane construct they've summoned. Thanks to the runestones you gathered, we know how to communicate with it. Talk to the construct and say \"Al'teth la c'tolgar.\" Got that? Repeat it? Close enough. Report back to me and let me know what happens!", completion = "Haha! Hah - HA! Night elf \"mages\" fleeing their own arcane creation. Your actions have made my month, {name}. That's why we blood elves don't use arcane constructs anymore - they've been outlawed for, oh, 1500 years. It's amusing to me to watch our foes repeat the mistakes of the past. \"Mages.\" Indeed.", objectives = "Speak with the Arcane Construct at the Darnassian Base Camp and utter the words of arcane power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14431] = { id = 14431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackmaw Scar", description = "The Blackmaw furbolg that live in this area have broken rank with their Timbermaw brethren as we began to aggressively settle Azshara. They've gone wild, {class}, and harass our forces at every turn. Worse, we have seen them engaging the night elves from Talrendis on friendly terms. We cannot allow the two to ally!\n\nJust southwest of here you will find a great scar across the earth where my scouts report night elven activity. Slay them and gather any intelligence you find.", progress = "The Blackmaw are ferocious. Were they ever to organize, they would prove to be an immense disruption to our work here.", completion = "I see... This definitely looks like a working draft of some sort of treaty. That's a worst-case scenario for us, {name}: Night elves coordinating attacks with entrenched furbolg allies.\n\nMy initial instinct - a full-out frontal assault - would only drive them into the arms of the Alliance. We will have to take a different approach...", objectives = "Slay 8 Talrendis Biologists and gather up Blackmaw Intelligence from one of the bodies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14432] = { id = 14432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pale Brew", description = "It looks like our Alliance foes have been making headway with their Blackmaw talks by conducting negotiations in the furbolg tongue. If we're to sabotage the treaty, we're going to have to do the same.\n\nIt's not as hard as it sounds, {name}. The Blackmaw make a potent herbal tea, the fumes of which will place one in a trance-like state where you'll start speaking in tongues. The Blackmaw tongue, specifically. Go to Blackmaw Hold southwest of here and get me some samples of that briaroot brew!", progress = "How goes the hunt? I sampled that briaroot stuff myself once, but it was too bitter, even for an old gravel-eater like myself.", completion = "Ah good, that's plenty. We'll boil this stuff up and you can bask in the fumes for a while - you'll be speaking like a furbolg in no time. Our plan is beginning to take shape...", objectives = "Gather up 10 samples of Briaroot Brew from outside Blackmaw Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14433] = { id = 14433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomacy by Another Means", description = "In order to infiltrate and disrupt the Blackmaw negotiations, we'll need to know where they're happening. In Blackmaw Hold to the southwest, I suspect you'll find night elven ambassadors milling around, making preparations.\n\n<Haggrum spits on the ground.>\n\nKill them at your leisure, and search the area for important documents. Oh, and grab a set of their ambassador's robes, we'll need them.", progress = "Do you have the robes? Andorel here has been whipping up some magic for us to use.", completion = "Excellent work! Let me see those documents. Hmm. Now we know exactly when and where the final negotiations will happen. Don't worry if those robes don't fit you - I've got it all worked out.", objectives = "Gather a Blackmaw Meeting Agenda at Blackmaw Hold, and kill a Talrendis Ambassador to collect her Ambassador's Robes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14434] = { id = 14434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rut'theran Village", objectives = "Are you ready to set sail, {name}?  Your people have been granted shelter in the lands of the kaldorei.\n\nDo not worry, {race}.  Your people will get a chance to fight for Gilneas again.  This time, with the full strength of the Alliance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14435] = { id = 14435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackmaw Doublecross", description = "Andorel here has crafted a little bit of magic for me. Come, stand next to my fire, and steep yourself in the fumes from the tea. Drape the robes around you and you'll take on the appearance of a night elven ambassador to the Blackmaw.\n\nDon your disguise and speak to Andorel here in camp. He'll teleport you to the heart of Blackmaw hold, where the negotiations are to take place. Speak with Chieftain Ungarl and sabotage the treaty. Then, kill as many Blackmaw as you can on the way back!", progress = "If our ruse pays off, {name}, we will forever drive a wedge between the Alliance and the Blackmaw.", completion = "Victory! The Blackmaw won't know who to trust anymore.\n\nWith that delicate bit of business complete, I can orchestrate a full-on assault against those beasts without worrying about them siding with the Alliance.\n\nYou do good work, {name}. Perhaps we should place you in the Horde diplomatic corps? Hah-har!", objectives = "Wear the Ambassador Disguise and talk to Andorel Sunsworn to teleport into Blackmaw Hold. Speak with Ungarl to wreck the negotiations, then kill 4 Blackmaw Warriors and 4 Blackmaw Shaman on your way out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14436] = { id = 14436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarven Digging", description = "There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings.\n\nCollect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools.\n\nYou can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.", objectives = "Collect 5 Prospector's Picks.\n\nAt a forge, smash the Prospector's Picks to create Broken Tools.\n\nBring 5 Broken Tools to Ahmo Thunderhorn in Bloodhoof Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14437] = { id = 14437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Earthmother", description = "For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, {name}.\n\nTravel to Bloodhoof Village and seek out the Ahmo Thunderhorn. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff.\n\nTake this totem to Ahmo. He will recognize my carvings and help you on your path.\n\nFollow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.", objectives = "Take the Totem of Hawkwind to Ahmo Thunderhorn in Bloodhoof Village. Follow the road out of Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14438] = { id = 14438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing the Land", description = "{name}, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as our elders have. Yet there is one that I would ask you to seek. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land.\n\nPalemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled.\n\nWords are no longer the answer.", progress = "If the Palemanes had respected the land and its inhabitants more, this conflict would have never occurred.", completion = "{name}, it is good you've taken the task seriously. Respect of the land and its creatures is important. Death and life are a circle... a necessity. One cannot exist without the other. Take time to ponder this and do well to never forget it.", objectives = "Kill 15 Palemane Gnolls then return to Ahmo Thunderhorn in Bloodhoof Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14439] = { id = 14439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey into Thunder Bluff", description = "You will now be revered within our great city. Any {race} worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our young leader, Baine Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.", sourceObjective = "Speak with Baine Bloodhoof in Thunder Bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[14440] = { id = 14440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Earthmother", description = "You have passed the Rites of the Earthmother and earned your place in Thunder Bluff.\n\nBut in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people.\n\nWe are hunters, {name}. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.", objectives = "Baine Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14441] = { id = 14441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrosh's Autograph", description = "They say that Garrosh Hellscream is one of the greatest heroes in the Horde! When I grow up, I want to be a hero of the Horde too!\n\nDo you know Garrosh, {name}? Could you do me a favor, please? Could you get his autograph for me? I dunno how to ask him, and he probably wouldn't listen to someone like me... but you! You're an adventurer, like him! I bet he'd give you his autograph easy!\n\nPlease?", objectives = "Travel to Grommash Hold in the heart of Orgrimmar's Valley of Strength to see about getting Garrosh Hellscream's autograph for your ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14442] = { id = 14442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Favorite Subject", description = "I don't know if you've noticed {name}, but this whole lab complex has gone south of cheese! I don't mind writing off all those hippogryphs, but my most prized experiment has gone missing: Subject Nine!\n\nSubject Nine is a raptor we imported from the Barrens. I wonder - is she still alive? Try checking above the main complex west of here, near the giant top secret rocket. You can't miss it.", completion = "Have you come to assist me with my work? My claws are quite dexterous, but I must reluctantly confess that my arms are debilitatingly short.", objectives = "Locate Subject Nine somewhere near the Secret Lab complex in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14443] = { id = 14443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battered Hilt", description = "This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art.\n\nThe graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Silver Covenant members would be interested in hearing about the recovery of such an artifact. Seek out their representative at Quel'Delar's Rest, south of the Argent Tournament Grounds.", progress = "What is it that you have there?", completion = "<Caladis takes the hilt from you and slowly turns it over in his hands.>\n\nThis seems somehow familiar, as though I should know its origins. You say you recovered this in the citadel? Most intriguing.\n\nThere are few who possess the ability to make such a blade. Perhaps they can tell us something about your find.", objectives = "Bring the Battered Hilt to Caladis Brightspear at Quel'Delar's rest, south of the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14444] = { id = 14444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What The Dragons Know", description = "There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recall seeing or hearing of a sword with these markings, but that doesn't mean that all is lost.\n\nKorialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Arcanist Tybalin inside the Silver Enclave in Dalaran.", completion = "We can't let that book remain in Sunreaver hands. If we hope to identify the sword and use it to our advantage, we have to find a way to capture the book Krasus lent them.", objectives = "Speak to Krasus at the top of Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14445] = { id = 14445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farewell, For Now", description = "Our destinies are forever intertwined. There are events taking place that are reshaping our world and ultimately will destroy it. We must put an end to them before it is too late.\n\nKnow that you can always count on me, <brother/sister>! We will meet again on the larger island. May you find peace until then, {name}.", completion = "Wow, oh wow! Is that who I think it is?\n\nYou rescued Thrall, Warchief of the Horde?!!!\n\n<Sassy gives you an appraising look.>\n\nWell, let's see about getting over to that larger island. I sure as heck don't want to swim the strait with all of those sharks down there.", objectives = "Speak with Sassy Hardwrench at the Wild Overlook on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14446] = { id = 14446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm!", description = "Hear my words, {class}!\n\nThe winds of change have gathered into a violent storm that sweeps across Azeroth.\n\nHave you the courage to face the true cause of our plight?\n\nMuster your resolve, {race}, and pray for the strength and fortune to see you through the trials that await.\n\nAn unexpected ally has issued a call for all that would hear. Peer into the Waters of Farseeing and behold the fate of the world!", objectives = "Nambria wants you to peer into the Waters of Farseeing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14447] = { id = 14447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.", sourceObjective = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14448] = { id = 14448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.", sourceObjective = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14449] = { id = 14449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Step", description = "What you see here is the work of the quilboar, young one. Year after year they have encroached on our village. The great cataclysm finally drove them from their dens to spread like locusts across the land, and now you see the result; my own mother, dead from their savagery.\n\nToday, you are of age. Today, you will take up your weapon and fight for the tribe, and avenge the Greatmother. Follow the path to the east, and find my son, Grull. He will lead you in our strike against the quilboar.", completion = "Welcome to your first true test as a {race}.", objectives = "Follow the path East out of Camp Narache and find Grull Hawkwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14450] = { id = 14450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Random Drop Test Progressive", description = "This quest tests random drops with progressive drop percentage.", objectives = "Get 10 Progressive Widgets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14451] = { id = 14451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Random Drop Flat Rate", description = "This quest tests random drops with flat rate drop percentage.", objectives = "Get 10 Flat Widgets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14452] = { id = 14452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Strength", description = "Behold, {name}. The very presence of the Bristleback is a blight. Nothing is left in their wake but corpses and barren land. Camp Narache could become what we see here in but a few days, unless we stand and fight.\n\nThis will be your Rite of Strength; the first ceremony of a tauren brave. Go into the heart of the thornsnarl and kill Bristleback quilboar, then return to me.", progress = "Get in there, {name}! We won't let any past. I want you in the midst of them, scattering them left and right!", completion = "You've fought well, {name}. We may yet be saved.", objectives = "Kill 6 Bristleback Invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14453] = { id = 14453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Humble Task", description = "All members of the tribe share in the harmony of life. We live together and work together.\n\nOur commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task.\n\nMy mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?", sourceObjective = "Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[14454] = { id = 14454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Warrior", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Brave Sharphorn, a young warrior trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save him!", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Brave Sharphorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14455] = { id = 14455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Thorncallers", description = "Knowing the ways of your prey is another aspect of the hunt. In the lands they come from, quilboar live in the shade and protection of huge thorned roots. When they move, their shamans seed and grow new roots for them to live in.\n\nThese thorns mar the land and choke out other life, turning the earth around them barren.  Go to the south and stop these thorncallers before they have a chance to continue, {name}.", completion = "With the corruptors slain, the Earth Mother will mend her own wounds in due time.  The roots are not meant to thrive here, and will wither.  Balance will return.", objectives = "Kill 7 Bristleback Thorncallers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14456] = { id = 14456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Courage", description = "One of the first lessons you should learn, {name}, is to never underestimate your prey.\n\nWhile we were distracted by the attack on Camp Narache, more of the Bristleback swept in unnoticed and stole a cache of our rifles. You can see them to the south now, filling the air with lead.\n\nThis is your Rite of Courage: brave the hail of gunfire, hunt the Bristleback gun thieves, and bring back our rifles.", progress = "How many have you brought me, initiate?", completion = "Well done, {name}. Respect your prey, and the danger it carries, but never fear it. In fear, you become prey yourself.", objectives = "Recover 7 Stolen Rifles from Bristleback Gun Thieves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14457] = { id = 14457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunreaver Plan", description = "One of my contacts in the Underbelly caught sight of a Sunreaver agent buying reagents from a dealer in the Black Market area. The Sunreavers normally aren't known for their interest in what goes on in the sewers, so that's a big indication they're planning something.\n\nHead into the Underbelly, find this Sunreaver agent, and take care of them. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let them get it back to Icecrown first.", progress = "Did you find anything of use on that agent?", completion = "<Arcanist Tybalin examines the captured orders.>\n\nThe agent you intercepted was supposed to transport the Wyrmrest Tome to Icecrown, after meeting with one Magister Hathorel in Sunreaver's Sanctuary. We have to get that book, {name}, and this is our chance. It's not going to be easy, though.", objectives = "Obtain the Sunreaver Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14458] = { id = 14458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go to Adana", description = "We've struck a great blow against the quilboar here. I will stay here, and hold the line, but you need to move on.\n\nSeek Adana Thunderhorn; she has taken a few braves to the southwest to root out the rest of the Bristleback.", completion = "More trials lay ahead, {name}. I hope you're prepared.", objectives = "Go to Adana Thunderhorn to the Southwest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14459] = { id = 14459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battleboars", description = "There are more threats to be dealt with here.  The Bristleback are taming wild boars to be used against us.\n\nThese armored battleboars have been abused beyond hope of recovery; they must be put down, for our safety and their peace.  Go to the pens to the south and slay them, {name}. Return to me afterwards.", completion = "Good work, {name}.  Those beasts could have been a greater threat than the quilboar themselves, if we had not taken action now.", objectives = "Kill 10 Armored Battleboars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14460] = { id = 14460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Honor", description = "Chief Squealer Thornmantle leads these quilboar. It was he that set upon Greatmother Hawkwind and took her life, leading the attack on Camp Narache. He fled and hid afterwards, but we've found him. He lurks to the west within his foul den of thorns, fending off any braves we send in after him.\n\nYou've proven yourself as a brave defender of our people, {name}. Kill Thornmantle and bring his mane back to Chief Hawkwind, in honor of our Greatmother!", progress = "Have you completed your trials, young one?", completion = "<Chief Hawkwind holds the mane of Thornmantle over his head.>\n\nThe Chief of the Bristleback is slain. Greatmother Hawkwind's spirit has been avenged!", objectives = "Kill Chief Squealer Thornmantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14461] = { id = 14461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feed of Evil", description = "We must do more than simply hunt boars here. The eyesore that has been left upon the land must be purged.\n\nTo give them a wild thirst for blood, the battleboars are force-fed raw flesh. Take this torch, and use it to burn the troughs of meat and gore to cinders.", progress = "Have all the troughs been burned?", completion = "You've not only wiped the boar pens clean, but put a stop to a horrible desecration.  Well done.", objectives = "Use Adana's Torch to set fire to all 3 Troughs in the Battleboar Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14462] = { id = 14462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's My Head?", description = "He's here, {name}! Captain Grunwald is a high-ranking Alliance officer from Northwatch Hold, no doubt here to coordinate an assault on Orgrimmar with his night elven allies. We have observed him entering the tower southwest of here. I want his head, {class}. I want to send it back to Northwatch to drive a wedge between our enemies!\n\nI've sent a goblin assassin, Slinky Sharpshiv, to the tower but she hasn't returned. Go find her. And get me that head!", completion = "You're just in time, {class}. I'm about to launch a lightning-strike precision assassination. Let's see...\n\nExplosives? Check.\nPneumatic grapplestabber? Check.\nPortable parachute? Check.\nCrippling nerve toxin?\n\n\n\nCheck. Let's do this thing.", objectives = "You've been sent to meet with the goblin assassin Slinky Sharpshiv at the base of the northern tower of Talrendis Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14463] = { id = 14463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horses for Duskhaven", description = "Saving the horses might've saved the rest of the town.  They have plenty of carriages in Duskhaven, but not enough horses to pull them.\n\nGo tell Mayor Armstead that the horses you saved are at her disposal.\n\nI'll get things ready and join you in a bit.", completion = "Excellent work, {name}.  I think I speak for everyone when I say the sooner we get out of here, the better.", objectives = "Speak to Gwen Armstead in Duskhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14464] = { id = 14464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Strike Assassination", description = "The base of the tower is patrolled by the Captain's elite guards. So here's what we're going to do: we're going to grapple straight up to the top, slice-and-dice the VIPs, and bail out using my portable low-altitude parachute. I'll rig the tower to explode behind us. You be sure to grab Captain Grunwald's head for Chawg. Got it?\n\nDo NOT accept this mission unless you are prepared for UNMITIGATED BADASSERY. Is that clear?", progress = "I trust you've got good news, {name}?", completion = "I'm impressed by the cleverness of our new goblin allies, but I'm even more impressed by you, {name}. Look at the gaze of terror frozen onto the Captain's face! He never saw your attack coming. Imagine the fear this will cause in Northwatch when they see what happened to one of their precious officers in night elf lands.\n\nWell done, {class}. Our assault proceeds...", objectives = "Talk to Slinky Sharpshiv to ascend the tower and assassinate Captain Grunwald. Collect Captain Grunwald's head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14465] = { id = 14465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Greymane Manor", description = "It's time for everyone to head to safety.  That includes you, {name}.  Head to Greymane Manor, the others will be there shortly.\n\nDon't worry about me, I'll make sure that everyone makes it out of here in one piece.  Yes, even the few ferals we have in the pens.\n\nOnce you get there, speak to Queen Greymane about the gravity of the situation.", completion = "{name}.  I've heard much about you.\n\nI understand you were crucial in my family's survival during the outbreak in Gilneas City.", objectives = "Speak to Queen Mia Greymane inside Greymane Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14466] = { id = 14466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The King's Observatory", description = "You ought to speak to Genn.  He's been locked up in his observatory ever since this ordeal started.\n\nI'm sure he's working on a plan for his people.  He's a very stubborn individual.", completion = "There you are, {name}.  I've been expecting you.\n\nI got word of your recovery and... wait -- do you feel that?", objectives = "Speak to King Genn Greymane in the observatory inside Greymane Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14467] = { id = 14467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alas, Gilneas!", objectives = "Look, {name}!  Look at what's become of Duskhaven!\n\nLook at what's become of the last safe place in Gilneas!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14468] = { id = 14468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Warm Body", description = "Oh have I got a deal for you! Immerse yourself in foreign cultures, go on epic adventures, blow things up, and get paid to do it! Sound too good to be true? Well it's not - this is what we do!\n\nIf you're interested, head over to Gallywix Defense Post on Forlorn Ridge to the north and look for Commander Molotov.", completion = "Latest recruit, eh?\n\nI'll make this short and sweet. We're under contract to keep the naga in the ruins from reaching Gallywix or his property. You handle whatever we ask of you, and I'll see to it that you get paid when all of your rounds are complete.\n\nWelcome to the Bilgewater Battalion.", objectives = "Report to Commander Molotov on Forlorn Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14469] = { id = 14469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand-me-downs", description = "First things first - we need more supplies for you and the other new recruits. There are some perfectly good standard issue packs on the bodies of our last round of recruits, in the minefield to the north.\n\nTaking their lessons to heart, I'd recommend you avoid stepping on mines yourself.", progress = "Nothing wrong with recycled goods.", completion = "You're a light-footed bugger, aren't ya? Good work.\n\nHere are a few of the supplies to keep you lively.", objectives = "Retrieve 12 Military Supply Packs from the central minefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14470] = { id = 14470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Military Breakthrough", description = "We've lost contact with Sergeant Dynamo, stationed at the next ridge to the north of the central minefield. They were probably overrun.\n\nHe had our last SFG. Go over there and get it back. Clear out any naga that have broken through while you're there.", progress = "Where's my rocket launcher, recruit?", completion = "Quick work there, recruit.\n\nShe's a beaut, isn't she? Assembled her myself. I've got special plans for this baby.", objectives = "Kill Warlord Krellian and recover the SFG.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14471] = { id = 14471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Degree Mortar", description = "Hey bud! Like explosions? Of course you do. Who doesn't like explosions?!\n\nI've got mortars set up on the ridge to the east to hold the naga back. Go forth, recruit. Mortar them... mortar them all! Ahahahah.", progress = "KABOOM!", completion = "Can you believe they PAY us to do this?", objectives = "Use a Goblin Mortar to slaughter 60 Spitelash Attackers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14472] = { id = 14472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In The Face!", description = "The naga are using those giants to stamp paths through our minefields. Time to put that SFG to use!\n\nHead over to the entrance to the southern minefield - I think you can figure out the rest.", completion = "BAM! In the face! Nice shot, kid.", objectives = "Use an SFG to kill an Enslaved Son of Arkkoroc in the southern minefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14473] = { id = 14473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Our Problem Now", description = "Looks like those monkeys will steal anything! Those thieving little monsters have driven the teraptor matriarch into a frenzy by stealing her eggs. Worse yet, the eggs have started to hatch! We've got hungry teraptor hatchlings running around all over the place, looking to make a quick meal out of us!\n\nWe didn't start this, but it's our problem now. You'll have to head into the jungle and kill those hungry teraptor hatchlings before they kill us all.", completion = "Let's just hope we don't have to deal with their mommy later. That would be very bad.", objectives = "Slay 6 Teraptor Hatchlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14474] = { id = 14474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Escape Pods", description = "{name}, I'm sorry, I thought you were dead!\n\nThis is just crazy. We sailed into a fight between the Alliance and Horde!\n\nYou know, our brothers and sisters still need to be rescued.\n\n<He points out all of the escape pods in the water around you.>\n\nI think I'm going to sit here a while longer and catch my breath. Can you swim around and let them out? Take my pair of thermohydratic flippers so you can get around faster.\n\nLet Sassy know that I'll swim in shortly.", completion = "Oh, thank heavens that you survived, {name}! I thought for sure that you'd drowned when I saw you go over the side!\n\n\n\nLook at all of these folks you saved!", objectives = "Rescue 6 Goblin Survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14475] = { id = 14475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grounded!", description = "Do you see a problem with these wind riders, {name}? They're not riding the wind! Every flight I send aloft gets peppered by night elf snipers.\n\nTalrendis sharpshooters are holed up in the southern-most tower, against the mountains. I sent one of these little goblin scrubs to take care of the tower, but I haven't heard a word from him. Go find Bombardier Captain Smooks and beat him with the hurry stick!", completion = "Reinforcements, at last!", objectives = "Find Bombardier Captain Smooks at the southernmost night elf tower at Talrendis Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14476] = { id = 14476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rigged to Blow", description = "This tower was out of cannon range, so I thought we'd blow it up the old-fashioned way - in person. We set all the main charges but the guards fought us back before we could arm the detonators.\n\n{name}! Get up there and arm the three detonators we placed around the base of the tower. Those things are wired into a pack of thermals I set up along the spine... It'll be some show!", progress = "Did you get 'em? Did you get all three?", completion = "Sweet. Let's torch this banana stand!", objectives = "Arm the three Explosive Charges located around the base of the southern-most tower at Talrendis Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14477] = { id = 14477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Push the Button!", description = "Lemme check the connections... and we're set. You do the honors, {name}. Push it. Push the button!\n\nPush the button, {name}!\n\nAfter the fireworks, go tell Kroum back at Valormok that his skies are clear.\n\nPush the button!", completion = "Yes, let them burn! Let them burn through the night, so that their flaming tower will light the battlefield beneath us as we rain terror upon their heads.\n\nThank you, {name}. Stay close: the invasion is about to begin...", objectives = "Detonate the explosives!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14478] = { id = 14478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Fishgut", description = "The Bilgewater Battalion are now accepting recruits for OPERATION FISHGUT.\n\nWages will consist of 1 gold piece at the time of operation completion for all active soldiers in good standing. All wages will be forfeited in the event of death. A fee of 20 silver will be charged for any resurrections performed in the line of duty.\n\nAll recruits are to report for duty directly to Commander Molotov under the main cannon.", completion = "Welcome back to duty soldier. Good to have you back.", objectives = "Report for active duty to Commander Molotov under the main cannon in Bilgewater Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14479] = { id = 14479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Are Many Like It", description = "Enough small talk. Get off your butt and onto a rocket, soldier.\n\nAnd remember, you don't get paid if you're dead.", completion = "Bumpy ride?", objectives = "Use a rocket to reach the Shattered Strand, and then report for duty to Lieutenant Drex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14480] = { id = 14480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extermination", description = "We're sending you in there to clean up this naga infestation. Lethal force has been authorized.\n\nGob Squad will be backing you up on this one, so it should be a cakewalk.", completion = "Your name's getting around... nearly Gob Squad status some would say. You're a vicious one.", objectives = "Kill 30 Spitelash Naga in the Ruins of Eldarath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14481] = { id = 14481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Abyss", description = "The Horde and Alliance are locked in battle with one another in the seas to the west.\n\nBelow them, a great host of enemies prepares to carry out a plan that could be the undoing of us all.\n\nI am sending you to speak with the admiral of the alliance forces. Share with him the vision you have seen. Convince him to focus his attention on the true threat below, before it grows too late...\n\nTo gain audience with the admiral, you must first enlist with the recruiter at the harbor.", sourceObjective = "Nambria wants you to speak to Recruiter Burns at Stormwind Harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[14482] = { id = 14482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Duty", description = "Citizen!\n\nAs you may have heard, the Horde's attacking just offshore. The fighting's been fierce and relentless.\n\nWe need every able body out there repelling the enemy!\n\nReport to the northernmost dock at once for transport to the battle.\n\nOh, and our official warships are... err, a bit late in their scheduled return. Don't worry though, we've commissioned mercenary vessels to serve in the meantime.\n\nHurry along now, {class}. Stormwind needs you!", completion = "Not exactly the battle you had anticipated, I'll wager. But a battle nonetheless, as you shall soon see....", objectives = "Ride the mercenary ship to battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14483] = { id = 14483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something is in the Air (and it Ain't Love)", description = "The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!", progress = "Did you take care of those no-good scheming villains?", completion = "What've you got there?\n\nOh hey, this is big. Real big. Most of the crazy details in one little package. Thanks - you really helped us reel this all in. Good working with ya.", objectives = "Bring the Faded Lovely Greeting Card to Detective Snap Snagglebolt in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14484] = { id = 14484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head of the Snake", description = "They taught us at officers camp to always cut off the head of the snake. Seemed dumb considering we never fought any snakes, but I guess it kind of makes sense now.\n\nTake your men in there and kill Lord Kassarus.", completion = "Glad you're on our side, soldier.", objectives = "Kill Lord Kassarus in the Temple of Zin-Malor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14485] = { id = 14485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ticker Required", description = "Our best demo-man, Ticker, is on assignment with the Gob Squad. He's got WAY more than enough explosives for all the runestones in the ruins.\n\nAll you have to do is get him there and keep him covered - he'll handle the rest.", progress = "Ticker's a man after my own heart. Couldn't be prouder.", completion = "The hope is that that cuts off a major source of their magic. The truth is, we don't really have a clue. Who can pass up an opportunity to blow some stuff up though.", objectives = "Bring Ticker into the ruins and cover him as he sets up bombs at 3 of the Spitelash Runestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14486] = { id = 14486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling the Goods", description = "Hey there, buddy. Want to make a quick buck?\n\nBring me back any highborne tablets you find in the ruins.", progress = "The blood elves eat those tablets up. Top dollar.", completion = "Excellent. Here's your cut.\n\nGood doing business with you.", objectives = "Collect 12 Highborne Tablets from the Ruins of Eldarath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14487] = { id = 14487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Beating Heart", description = "Commander Molotov found a party at the Secret Lab willing to act as buyer for the artifact that you scouted out earlier.\n\nUndoubtedly, it's still in the center of the ruins with the High Priestess, where you initially spotted it. Get it back here undamaged, soldier.", progress = "I love it when people leave priceless artifacts just lying around.", completion = "Hahah! It's HUGE!\n\nWe'll have you take it back to Uncle Bedlam as soon as everything's cleaned up here and you're ready to go.", objectives = "Recover the Heart of Arkkoroc from the center of the Ruins of Eldarath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14488] = { id = 14488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Been Served", description = "You made it, huh? Good. I've been waiting for help. No time like the present to act, right?\n\nTake this kit and head deeper inside to serve papers to the leader of that scumbag chemical company, Hummel. The paper's inside. So's a little something to protect you from any chemical tricks they might pull. Use one of the neutralizers when the time comes, all right?", objectives = "Serve the Court Subpoena to Apothecary Hummel in Shadowfang Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14491] = { id = 14491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Earth", description = "Until recently, a group of dwarves intruded on our lands to the west, carving the earth apart senselessly to search for treasure.  When the very earth itself tore apart, the spirits of the land they had abused rose up and took their revenge.\n\nThe agitated earth spirits still roam the former dig site, {name}.  We must offer them appeasement.\n\nTake this drum with you to the west and play to the spirits.  The rhythm may calm their fury and confusion.", completion = "The land is clearly still in great upheaval if it took such effort to calm.\n\nRemember this, {name}.  Do not forget seeing the fate of those who would scar the Earth Mother.", objectives = "Use the Drums of the Soothed Earth to calm 6 Agitated Earth Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[20438] = { id = 20438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Disguise", description = "Getting you inside the Sunreaver's Sanctuary will be tougher than it appears. Only those who possess Sunreaver tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work.\n\nOn the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.", progress = "Was Shandy able to help you get a Sunreaver tabard?", completion = "I knew Shandy would find a way to come through for us. Let me get this enchanted and ready for you to use. The sooner you get done with the tabard, the sooner we can get it back to Shandy and the better the chances that its owner will never have missed it.", objectives = "Obtain a Borrowed Tabard from Shandy Glossgleam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[20439] = { id = 20439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meeting With The Magister", description = "I've placed an enchantment on the tabard that should allow you to slip past the Sunreaver Sanctuary's defenses for a short period of time. You should have enough time to find your way into The Filthy Animal and meet up with the Sunreaver contact there, one Magister Hathorel.\n\nObtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest while your disguise holds, and return it to me.", progress = "Have you recovered that book?", completion = "Excellent work. Now that this is in our hands, we must get it to Caladis Brightspear as soon as possible. We can't risk the book falling back into Sunreaver hands.\n\nI'll ensure that Shandy Glossgleam gets his tabard back without incident, along with a healthy reward for his help.", objectives = "Retrieve the Ancient Dragonforged Blades tome from Magister Hathorel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[20440] = { id = 20440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poison Water", description = "Our sacred wells have been tainted, and I will need your help to fix this.\n\nTo cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual.\n\nFirst we will create a cleansing totem for the Winterhoof Water Well.  To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons.  They are to the southwest.\n\nReturn to me with the paws and talons, {name}.", progress = "Do you have the paws and talons, {name}?", completion = "You have done well, {name}.  I will take these and bind their power into a totem of cleansing.", objectives = "Collect 6 Prairie Wolf Paws and 4 Plainstrider Talons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[20441] = { id = 20441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Vision", description = "Again, be sure you are ready to leave Bloodhoof Village behind, {name}. The next step on your journey will take you far from here.\n\nYour path continues to lead onward, across the fields of Mulgore, the eyes of the Earth Mother on you at all times. When you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, your eyes will be opened, and the spirits will guide you.", completion = "Be not afraid, {name}. You have successfully passed the Rite of Vision.", objectives = "Consume the Water of Vision in front of the tribal fire in Bloodhoof Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[23733] = { id = 23733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Earthmother", description = "Today, you have undertaken a rite of passage far more difficult than we ask of most of our youths. Be proud. Now, it is time for you to continue on your journey.\n\nTo the west, beyond our burial ground, you will find a path winding up the mesa. Follow it to the top, and speak with Dyami Windsoar.\n\nWalk with the Earth Mother, friend. You will always be welcome here.", completion = "If you are prepared to leave Camp Narache behind, I will help call the spirits to guide you onwards.", objectives = "Speak to Dyami Windsoar atop Fargaze Mesa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24215] = { id = 24215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of the Winds", description = "Look, {name}. The rolling plains of Mulgore stretch before you: our home, the cradle of the Earth Mother. Here she provides us with all we could ever need, a peaceful and verdant land. This is what you will fight to protect.\n\nYour journey will take you far beyond her sheltering arms, to the farthest and cruelest regions of this world, and beyond.\n\nBelow us is Bloodhoof Village. The first step on your true path begins now. Drink deep of the Water of Vision, and let the spirits guide you onward.", completion = "Welcome to Bloodhoof Village, hero.  I am glad the spirits have guided you safely here.", objectives = "Drink the Water of Vision.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24216] = { id = 24216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24217] = { id = 24217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24218] = { id = 24218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24219] = { id = 24219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24220] = { id = 24220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", objectives = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24221] = { id = 24221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", objectives = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24223] = { id = 24223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", objectives = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24224] = { id = 24224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24225] = { id = 24225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24226] = { id = 24226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", objectives = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24426] = { id = 24426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", objectives = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24427] = { id = 24427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", objectives = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24428] = { id = 24428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Zardeth of the Black Claw.", progress = "By Nozdormu's teeth!", completion = "What? How did you get this? Isn't she... Never mind the details, I suppose. You'll be wanting one of these baubles as recompense, no doubt.", objectives = "Take the Head of Onyxia to Zardeth of the Black Claw in the basement of the Slaughtered Lamb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24429] = { id = 24429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Arnak Fireblade.", progress = "What is the meaning of this?!", completion = "You've brought me the head of someone who is... No, best not to think about it too hard. You'll be wanting recompense for your heroic deeds, no doubt.", objectives = "Take the Head of Onyxia to Arnak Fireblade in the Cleft of Shadow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24430] = { id = 24430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacken the Skies", description = "{name}! Give us a hand here, will ya? Gorsch here had a bad experience at the all-you-can-eat seafood joint back in town, and now we're short a pilot.\n\nMy job was to take out those elven glaive throwers before they cut our air units to ribbons. Hop on this wind rider and take to the skies! One of my bombardier buddies will ride with you and bomb the targets at your command.\n\nAnd hey! Chuck a bomb straight at the night elven command center - the large building south of here, beside the bridge. Glorious!", progress = "More bombs. More bombs!", completion = "Oh yeah! I love the smell of freshly-cratered dirt!\n\nWord around camp is that the elven front line is collapsing back toward the river. Talk to Chawg and see if there's anything you can do to help seal the deal.", objectives = "Mount a Grounded Wind Rider and fly over Talrendis Point. Destroy 6 Talrendis Glaive Throwers and bomb the Command Center.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24431] = { id = 24431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waterlogged Recipe", description = "This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....", progress = "Wine is only as fine as the person drinking it, I always say.", completion = "This is quite a find, {name}.  I can't have you selling this to anyone else, so I'm willing to offer generously.", objectives = "Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24432] = { id = 24432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Legs", description = "Welcome to The Briny Cutter, {class}.\n\nI am Erunak, the last surviving passenger of this once-proud vessel.\n\nI'm afraid your travails have only just begun. The naga have been attacking here relentlessly.\n\nYou're not equipped to be of much help down here yet, but I can remedy that.\n\nJust outside this ship live a special breed of starfish. Bring me some of them along with a conch shell. I'll prepare an enchantment that should help to increase your chances of survival.", progress = "It is good to see that you're still alive, {race}.\n\nHave you found the items I require?", completion = "Here you are, {class}. With this you should find maneuvering in the sea to be nearly effortless. \n\nNow we must get to work. There is much to be done in little time.", objectives = "Erunak in The Briny Cutter wants you to bring him 3 Saltwater Starfish and a Conch Shell from Seafarer's Tomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24433] = { id = 24433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Feast on Fear", description = "Our grunts are strong but have no initiative. They're fighting toe-to-toe on the front lines. But an independent {class} like yourself - well, someone like you can slip behind the lines and cause some real havoc deep within the enemy redoubt.\n\nCut a swath of destruction through the heart of Talrendis, {name}! Slay our foes in territory they think is secure, leaving blood and fear in your wake.", completion = "Lok'tar ogar, {name}! As they discover the bodies of their comrades they will learn that no place is safe from the fury of the horde, and their will to fight will crumble.", objectives = "Fight your way across Talrendis Point, slaying 12 Talrendis Defenders and 6 Talrendis Sentinels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24434] = { id = 24434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commando Drop", description = "Are you sensitive to the tremors of the local ley-lines, {name}? I can feel the occasional thrum, like the plucking of a string. It's the kind of resonance I'd expect from a long-range summoning spell. The Lorekeepers in Talrendis, with their laughably primitive magics, are trying to summon in backup from Darnassus.\n\nWe can use this to our advantage, {name}. If you can compromise their summoning stone, we can teleport a crack team of commandos behind enemy lines.\n\nLocate the summoning stone in Talrendis!", progress = "If Andorel's instructions are to be believed, it should be easy to refocus the stone's energies.", completion = "Images of a great and distant tree flood your mind. Your stomach lurches as you reorient the stone, briefly filling your senses with visions of a fiery portal, a towering mountain, a frigid wasteland, and a terrible scar across the earth.\n\nAfter a moment, the magical energies of the stone calm, and you feel you are but a step away from Valormok. Andorel's invasion can begin...", objectives = "Slay 5 Talrendis Lorekeepers and locate a Lorekeeper Summoning Stone somewhere within Talrendis Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24435] = { id = 24435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mop Up", description = "There are a lot of naga left on this beach. Looks like you have some wet work ahead of you, <son/girl>.", completion = "Good clean fun.", objectives = "Kill 12 Spitelash Naga on the Shattered Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24436] = { id = 24436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halo Drops", description = "We've got \"soldiers\" all over the beach trying to get out of their work by dying on us. Find the slackers and use this flaregun to call in a priest to take care of the situation.\n\nWe can't have men thinking they can get off that easy.", completion = "Fine job there, bud. We'll have this beach cleaned up in no time.", objectives = "Call in Airborne Priests at the bodies of 8 Wounded Soldiers on the Shattered Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24437] = { id = 24437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Come, First Served", description = "There's some gorgeous beach front property along the shore. I can market this stuff for 10 times what construction will cost me.\n\nThe prime spots are that naga pagoda to the south, the tower right next to the water, and the ruins at the far northern end of the beach. I'll give you some coin if you claim them for me before the fighting clears out.", completion = "Hah hah! Brilliant. Right fine job there, boy.", objectives = "Plant Ruckus' Territorial Claim Flag next to the prime real estate locations along the Shattered Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24438] = { id = 24438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exodus", description = "We have no choice, {name}.  We must move further inland.\n\nI don't like it one bit, but we're vulnerable here.\n\nReturn to the stables below the manor.  Let's get everybody on carriages and send them eastbound.  I pray it's not too late.", completion = "Thanks for stopping, {name}.  Our carriage got hit pretty bad.\n\nThe one in front of us got it worse.", objectives = "Board a carriage below Greymane Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24439] = { id = 24439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest of Azshara", description = "{name}! Was it you who piloted the wind rider who bombed the command center? It was a direct hit!\n\nMy scouts tell me that you gravely wounded Jarrodenus, flight master of the night-elven skychasers and de facto commander of the opposition.\n\nThe opportunity to strike is now - I don't have time to assemble a full assault. Rush the command center building and kill Commander Jarrodenus before his backup arrives. Bring me his head... and Azshara is ours!", progress = "Is Jarrodenus still barking orders, or have you removed from him the burden of his head?", completion = "...Then it is done!\n\n<Chawg surveys the battlefield.>\n\nThere are still pockets of resistance around our camp, but this rearguard action appears to be masking a full-fledged retreat to Ashenvale. Azshara is ours!\n\nThe Warchief will hear of this victory and your part in it. But we will surely need the help of a {class} like you elsewhere. Be sure to speak with Kroum here in camp before you leave.", objectives = "Slay Commander Jarrodenus in Talrendis Point and collect his head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24440] = { id = 24440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  The well is to the southeast, but be warned: whoever did this may still be there, laying in wait.\n\nThis may prove very dangerous, {name}.  Be careful...but do not let the defilers of our well escape.", completion = "The Grimtotem...\n\n<Mull scowls.>\n\nI'd hoped to see the end of my days before {race} attacked other {race} senselessly on the very plains of Mulgore.  But be proud, {name}.  You have done a great thing for the land, and for our people.", objectives = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24441] = { id = 24441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderhorn Totem", description = "There is more work to be done.  We must create a new totem to cleanse the Thunderhorn Well.\n\nYou must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me.\n\nYou will find the prairie stalkers and flatland cougars to the east and west.", progress = "{name}, do you have the claws I sent you to gather?  The Thunderhorn Water Well grows more tainted with each passing hour!", completion = "Thank you, {name}.  The purity with which these beasts hunt is vital in the creation of the next cleansing totem.\n\nThe Thunderhorn Well is a symbol of my own tribe, and to know it is being desecrated by our own kind raises a fury in me I haven't felt for years.", objectives = "Collect 6 Stalker Claws and 6 Cougar Claws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24442] = { id = 24442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Plans Of The Kvaldir", description = "Looking over the captured attack plans, you find a map of the Eastern Kingdoms and Kalimdor with major settlements marked. Reading over the orders, you learn that  Kvaldir captains have drafted plans for a series of devastating raids.\n\nAccording to the orders, the attacks are to begin after Mistcaller Yngvar \"consults the Heart of the Mists.\" Perhaps you could delay the attacks by capturing the omen from the Mistcaller's Cave on the western side of Hrothgar's Landing and notify Justicar Mariel Trueheart.", progress = "What is it that you've found, {name}?", completion = "<Mariel accepts the orders and the captured seeing crystal and examines both.>\n\nGood work, {name}, and quick thinking. I'm sure the theft of this trinket won't slow them down for long, but I think you've bought us time to warn the leaders of the Horde and Alliance about the impending attacks.", objectives = "Recover the Heart of the Mists and bring it and the Kvaldir Attack Plans to Justicar Mariel Trueheart at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24443] = { id = 24443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Hunter", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Honu Staghunter, a young hunter trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Honu Staghunter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24444] = { id = 24444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Shaman", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Miira Thunderhoof, a young shaman trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Miira Thunderhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24445] = { id = 24445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Druid", description = "It's fallen to some of our youngest to defend our camp, {name}, and many of our bravest apprentices are out there as we speak, fighting the quilboar.  I fear for their safety...\n\nPlease, look for the young druid Keshu Treehoof to the east, deep within quilboar territory. If you find her and the other apprentices alive, they may be able to help you.", objectives = "Find Keshu Treehoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24446] = { id = 24446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Sunwalker", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Bowe Dawnhorn, a young Sunwalker, away in one of their foul cages. Please, find a key on one of the quilboar's bodies and go save him!", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Bowe Dawnhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24447] = { id = 24447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Seer", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Seer Skyhoof, a young seer, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Seer Skyhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
